/** All 522 entries for zizhitongjian ch.158 (apply by zh text) */
/** Translator: Garrett M. Petersen (2026); Model: Composer 2.5 */
export const entries = [
  { zh: "資治通鑑 第158卷", literal: "Comprehensive Mirror in Aid of Governance, Volume 158", idiomatic: "Comprehensive Mirror in Aid of Governance, Volume 158" },
  { zh: "【梁紀十四】　起著雍敦牂，盡閼逢困敦，凡七年。", literal: "[Liang Records 14] From Zhuoyong Dunzhang through Quefeng Kundun; seven years in all.", idiomatic: "[Liang Records 14] The span runs from Zhuoyong Dunzhang through Quefeng Kundun—seven years in all." },
  { zh: "高祖武皇帝十四大同四年（", literal: "Great Ancestor Emperor Wu, year 14 of the Datong era (", idiomatic: "Emperor Wu of Liang, fourteenth year of Datong (" },
  { zh: "戊午，公元五三八年）", literal: "wuwu, 538 CE)", idiomatic: "wuwu, AD 538)" },
  { zh: "春，正月，辛酉朔，日有食之。", literal: "In spring, the first month, on the new moon of xinyou, there was a solar eclipse.", idiomatic: "In spring, the first month, on the new moon of xinyou, the sun was eclipsed." },
  { zh: "東魏碭郡獲巨像，送鄴。", literal: "Eastern Wei's Dang commandery obtained a colossal image and sent it to Ye.", idiomatic: "Eastern Wei's Dang commandery unearthed a colossal image and sent it to Ye." },
  { zh: "丁卯，大赦，改元元象。", literal: "On dingmao, a general amnesty was proclaimed and the era name was changed to Yuanxiang.", idiomatic: "On dingmao the court proclaimed a general amnesty and adopted the era name Yuanxiang." },
  { zh: "二月，己亥，上耕藉田。", literal: "In the second month, on jihai, the emperor plowed the sacred field.", idiomatic: "In the second month, on jihai, the Liang emperor performed the ceremonial plowing of the sacred field." },
  { zh: "東魏大都督善無賀拔仁攻魏南汾州，刺史韋子粲降之，丞相泰滅子粲之族。", literal: "Eastern Wei Grand Commander Heluoba Ren of Shanwu attacked Western Wei's Nanfen province; Inspector Wei Zican surrendered; Chancellor Yuwen Tai exterminated Zican's clan.", idiomatic: "Eastern Wei's Grand Commander Heluoba Ren of Shanwu attacked Western Wei's Nanfen province. Inspector Wei Zican surrendered, and Chancellor Yuwen Tai wiped out Zican's clan." },
  { zh: "東魏大行台侯景等治兵於虎牢，將復河南諸州，魏梁回、韋孝寬、趙繼宗皆棄城西歸。", literal: "Eastern Wei Grand Commissioner Hou Jing and others mustered troops at Hulao to recover the Henan provinces; Western Wei's Liang Hui, Wei Xiaokuan, and Zhao Jizong all abandoned their cities and withdrew west.", idiomatic: "Eastern Wei Grand Commissioner Hou Jing and others mustered troops at Hulao to retake the Henan provinces. Liang Hui, Wei Xiaokuan, and Zhao Jizong of Western Wei abandoned their posts and withdrew west." },
  { zh: "侯景攻廣州，數旬，未拔，聞魏救兵將至，集諸將議之，行洛州事盧勇請進觀形勢。", literal: "Hou Jing attacked Guang province; for many weeks he could not take it. Hearing that Western Wei relief was coming, he gathered his generals to discuss the matter; Lu Yong, acting governor of Luozhou, asked to advance and reconnoiter.", idiomatic: "Hou Jing besieged Guang province for weeks without success. When word came that Western Wei relief was near, he called his generals to council; Lu Yong, acting governor of Luozhou, asked leave to ride ahead and scout." },
  { zh: "乃帥百騎至大隗山，遇魏師。", literal: "He then led a hundred horsemen to Mount Dawei and encountered the Western Wei army.", idiomatic: "He led a hundred horsemen to Mount Dawei and ran into the Western Wei army." },
  { zh: "日已暮，勇多置幡旗於樹顛；", literal: "The sun had already set; Yong planted many banners atop the trees;", idiomatic: "The sun was down; Yong planted banners thick on the treetops;" },
  { zh: "夜，分騎為十隊，鳴角直前，擒魏儀同三司程華，斬儀同三司王征蠻而還。", literal: "at night he divided his riders into ten squads, sounded horns, and charged straight ahead, capturing Western Wei Yitong Sansi Cheng Hua and beheading Yitong Sansi Wang Zhenman before returning.", idiomatic: "that night he split his riders into ten squads, sounded horns, and charged straight in—capturing Western Wei's Yitong Sansi Cheng Hua, beheading Yitong Sansi Wang Zhenman, and riding back." },
  { zh: "廣州守將駱超遂以城降東魏，丞相歡以勇行廣州事。", literal: "Guangzhou's defender Luo Chao then surrendered the city to Eastern Wei; Chancellor Gao Huan put Yong in charge of Guang province.", idiomatic: "Guangzhou's commander Luo Chao surrendered to Eastern Wei; Gao Huan put Yong in charge of the province." },
  { zh: "勇，辯之從弟也。", literal: "Yong was a cousin of Bian.", idiomatic: "Yong was a cousin of Bian." },
  { zh: "於是南汾、穎、豫、廣四州復入東魏。", literal: "Nanfen, Ying, Yu, and Guang provinces thus returned to Eastern Wei.", idiomatic: "Nanfen, Ying, Yu, and Guang provinces thus returned to Eastern Wei." },
  { zh: "初，柔然頭兵可汗始得返國，事魏盡禮。", literal: "Earlier, when the Rouran khan Toubing had regained his realm, he served Western Wei with full courtesy.", idiomatic: "When the Rouran khan Toubing first regained his realm, he had served Western Wei with full courtesy." },
  { zh: "及永安以後，雄據北方，禮漸驕倨，雖信使不絕，不復稱臣。", literal: "After the Yongan era he held the north in strength; his courtesy grew arrogant, and though envoys still passed between them, he no longer styled himself a subject.", idiomatic: "After the Yongan era he dominated the north; his courtesy turned arrogant, and though envoys still passed, he no longer called himself a subject." },
  { zh: "頭兵嘗至洛陽，心慕中國，乃置侍中、黃門等官；", literal: "Toubing had once come to Luoyang, admired China, and set up offices such as Attendant-in-Ordinary and Yellow Gate;", idiomatic: "Toubing had once visited Luoyang, admired China, and created offices such as Attendant-in-Ordinary and Yellow Gate;" },
  { zh: "後得魏汝陽王典簽淳於覃，親寵任事，以為秘書監，使典文翰。", literal: "later he obtained Chunyu Tan, clerk to Western Wei's Prince of Ruyang, favored him, made him Secretary Supervisor, and had him handle documents.", idiomatic: "later he won over Chunyu Tan, a clerk to Western Wei's Prince of Ruyang, favored him, made him Secretary Supervisor, and put him in charge of documents." },
  { zh: "及兩魏分裂，頭兵轉不遜，數為邊患。", literal: "When the two Weis split, Toubing grew more insolent and repeatedly raided the border.", idiomatic: "After the two Weis split, Toubing grew more insolent and raided the frontier again and again." },
  { zh: "魏丞相泰以新都關中，方有事山東，欲結婚以撫之，以舍人元翌女為化政公主，妻頭兵弟塔寒。", literal: "Western Wei Chancellor Yuwen Tai, having moved the capital to Guanzhong and being occupied with Shandong, wished to pacify him by marriage: he made Gentleman Yuan Yi's daughter Princess of Huazheng and gave her to Toubing's brother Tahan.", idiomatic: "Yuwen Tai, with the capital now in Guanzhong and his hands full in Shandong, sought to pacify him by marriage—making Gentleman Yuan Yi's daughter Princess of Huazheng and giving her to Toubing's brother Tahan." },
  { zh: "又言於魏主，請廢乙弗後，納頭兵之女。", literal: "He also urged the Western Wei sovereign to depose Empress Yifu and take Toubing's daughter.", idiomatic: "He also urged the Western Wei emperor to depose Empress Yifu and take Toubing's daughter." },
  { zh: "甲辰，以乙弗後為尼，使扶風王孚迎頭兵女為後。", literal: "On jiachen, Empress Yifu was made a nun, and the Prince of Fufeng, Fu, was sent to welcome Toubing's daughter as empress.", idiomatic: "On jiachen Empress Yifu was tonsured, and the Prince of Fufeng, Fu, was sent to welcome Toubing's daughter as empress." },
  { zh: "頭兵遂留東魏使者元整，不報其使。", literal: "Toubing then detained Eastern Wei's envoy Yuan Zheng and gave no reply to their mission.", idiomatic: "Toubing then detained Eastern Wei's envoy Yuan Zheng and sent no answer to their mission." },
  { zh: "三月，辛酉，東魏丞相歡以沙苑之敗，請解大丞相，詔許之；", literal: "In the third month, on xinyou, Eastern Wei Chancellor Gao Huan, because of the defeat at Shaya, asked to resign as Grand Chancellor; the edict permitted it;", idiomatic: "In the third month, on xinyou, Gao Huan asked to resign as Grand Chancellor after the defeat at Shaya; the court assented;" },
  { zh: "頃之，復故。", literal: "shortly afterward he was restored as before.", idiomatic: "shortly afterward he was restored as before." },
  { zh: "柔然送悼後於魏，車七百乘、馬萬匹、駝二千頭。", literal: "The Rouran sent their empress to Western Wei with seven hundred carriages, ten thousand horses, and two thousand camels.", idiomatic: "The Rouran sent their empress to Western Wei with seven hundred carriages, ten thousand horses, and two thousand camels." },
  { zh: "至黑鹽池，遇魏所遣鹵簿儀衛。", literal: "At Black Salt Pool she met the honor guard Western Wei had dispatched.", idiomatic: "At Black Salt Pool she met the honor guard Western Wei had dispatched." },
  { zh: "柔然營幕，戶席皆東向，扶風王孚請正南面，後曰：「我未見魏主，固柔然女也。", literal: "In the Rouran camp every tent and seat faced east; the Prince of Fufeng, Fu, asked the empress to face due south; the empress said, \"I have not yet seen the Western Wei sovereign—I am still a Rouran woman.", idiomatic: "In the Rouran camp every tent and seat faced east; the Prince of Fufeng, Fu, asked the empress to face due south. She said, \"I have not yet seen the Western Wei emperor—I am still a Rouran woman." },
  { zh: "魏仗南面，我自東向。", literal: "Western Wei's escort faces south; I face east myself.", idiomatic: "Let Western Wei's escort face south; I face east.\"" },
  { zh: "」丙子，立皇后郁久閭氏。", literal: "\" On bingzi, Empress Yujiu Lü was installed.", idiomatic: "On bingzi Empress Yujiu Lü was installed." },
  { zh: "丁丑，大赦。", literal: "On dingchou, a general amnesty was proclaimed.", idiomatic: "On dingchou the court proclaimed a general amnesty." },
  { zh: "以王盟為司徒。", literal: "Wang Meng was made Minister over the Masses.", idiomatic: "Wang Meng was made Minister over the Masses." },
  { zh: "丞相泰朝於長安，還屯華州。", literal: "Chancellor Yuwen Tai attended court at Chang'an, then returned to camp at Huazhou.", idiomatic: "Yuwen Tai attended court at Chang'an, then returned to camp at Huazhou." },
  { zh: "夏，四月，庚寅，東魏高歡朝於鄴；", literal: "In summer, the fourth month, on gengyin, Eastern Wei's Gao Huan attended court at Ye;", idiomatic: "In summer, the fourth month, on gengyin, Gao Huan of Eastern Wei attended court at Ye;" },
  { zh: "壬辰，還晉陽。", literal: "on renchen he returned to Jinyang.", idiomatic: "on renchen he returned to Jinyang." },
  { zh: "五月，甲戌，東魏遣兼散騎常侍鄭伯猷來聘。", literal: "In the fifth month, on jiaxu, Eastern Wei sent Acting Cavalier Attendant-in-Ordinary Zheng Boyou on a friendly mission.", idiomatic: "In the fifth month, on jiaxu, Eastern Wei sent Acting Cavalier Attendant-in-Ordinary Zheng Boyou on a friendly mission." },
  { zh: "秋，七月，東魏荊州刺史王則寇淮南。", literal: "In autumn, the seventh month, Eastern Wei's Jing province inspector Wang Ze raided Huainan.", idiomatic: "In autumn, the seventh month, Eastern Wei's Jing province inspector Wang Ze raided Huainan." },
  { zh: "癸亥，詔以東冶徒李胤之得如來捨利，大赦。", literal: "On guihai, an edict proclaimed a general amnesty because the eastern-smelting convict Li Yinzhi had obtained a Buddha relic.", idiomatic: "On guihai an edict proclaimed a general amnesty because the eastern-smelting convict Li Yinzhi had obtained a Buddha relic." },
  { zh: "東魏侯景、高敖曹等圍魏獨孤信於金墉，太師歡帥大軍繼之；", literal: "Eastern Wei's Hou Jing, Gao Aocao, and others besieged Western Wei's Dugu Xin at Jinyong; Grand Mentor Gao Huan led a great army in support;", idiomatic: "Eastern Wei's Hou Jing, Gao Aocao, and others besieged Dugu Xin at Jinyong; Grand Mentor Gao Huan followed with a great army;" },
  { zh: "景悉燒洛陽內外官寺民居，存者什二三。", literal: "Jing burned every official temple and dwelling inside and outside Luoyang; barely one or two in ten survived.", idiomatic: "Jing burned every official temple and dwelling inside and outside Luoyang; barely one or two in ten survived." },
  { zh: "魏主將如洛陽拜園陵，會信等告急，遂與丞相泰俱東，命尚書左僕射周惠達輔太子欽守長安，開府儀同三司李弼、車騎大將軍達奚武帥千騎為前驅。", literal: "The Western Wei emperor was about to go to Luoyang to worship the imperial tombs when Xin's urgent report arrived; he went east with Chancellor Yuwen Tai, left Left Vice Director Zhou Huida to assist Crown Prince Qin at Chang'an, and sent Kaifu Yitong Sansi Li Bi and Grand General of Cavalry Daxi Wu ahead with a thousand horsemen.", idiomatic: "The Western Wei emperor was about to visit the Luoyang tombs when Xin's urgent report arrived. He marched east with Yuwen Tai, left Zhou Huida to assist Crown Prince Qin at Chang'an, and sent Li Bi and Daxi Wu ahead with a thousand horsemen." },
  { zh: "八月，庚寅，丞相泰至谷城，侯景等欲整陳以待其至，儀同三司太安莫多婁貸文請帥所部擊其前鋒，景等固止之。", literal: "In the eighth month, on gengyin, Chancellor Yuwen Tai reached Gucheng; Hou Jing and the others meant to form battle lines and await him; Yitong Sansi Mo Duo Lou Daiwen asked to lead his division against the vanguard, but Jing and the rest firmly stopped him.", idiomatic: "In the eighth month, on gengyin, Yuwen Tai reached Gucheng. Hou Jing and the others meant to form battle lines and await him; Yitong Sansi Mo Duo Lou Daiwen asked to lead his division against the vanguard, but Jing and the rest overruled him." },
  { zh: "貸文勇而專，不受命，與可朱渾道元以千騎前進。", literal: "Daiwen was brave and willful; he disobeyed orders and advanced with Kezhunhun Daoyuan at the head of a thousand horsemen.", idiomatic: "Daiwen was brave and willful; he disobeyed orders and rode forward with Kezhunhun Daoyuan at the head of a thousand horsemen." },
  { zh: "夜，遇李弼、達奚武於孝水。", literal: "By night they met Li Bi and Daxi Wu at the Xiao River.", idiomatic: "By night they met Li Bi and Daxi Wu at the Xiao River." },
  { zh: "弼命軍士鼓噪，曳柴揚塵，貸文走，弼追斬之，道元單騎獲免，悉俘其眾送恆農。", literal: "Bi ordered his men to shout and beat drums, drag brushwood, and raise dust; Daiwen fled; Bi pursued and beheaded him; Daoyuan escaped alone on horseback; Bi captured the whole force and sent it to Hengnong.", idiomatic: "Bi ordered his men to shout and drum, drag brushwood, and raise dust. Daiwen fled; Bi ran him down and beheaded him. Daoyuan escaped alone; Bi took the whole force prisoner and sent them to Hengnong." },
  { zh: "泰進軍瀍東，侯景等夜解圍去。", literal: "Yuwen Tai advanced east of the Chan River; Hou Jing and the others lifted the siege by night and withdrew.", idiomatic: "Yuwen Tai advanced east of the Chan; Hou Jing and the others lifted the siege by night and withdrew." },
  { zh: "辛卯，泰帥輕騎追景至河上，景為陳，北據河橋，南屬邙山，與泰合戰。", literal: "On xinmao, Yuwen Tai led light cavalry in pursuit of Jing to the river; Jing formed his line with the river bridge to the north and the Mang hills to the south, and joined battle with Yuwen Tai.", idiomatic: "On xinmao Yuwen Tai led light cavalry after Jing to the river. Jing formed his line with the river bridge to the north and the Mang hills to the south, and closed with Yuwen Tai." },
  { zh: "泰馬中流矢驚逸，遂失所之。", literal: "Yuwen Tai's horse was struck by an arrow, panicked, and bolted; he lost his way.", idiomatic: "Yuwen Tai's horse took an arrow, panicked, and bolted; he was separated from his men." },
  { zh: "泰墜地，東魏兵追及之，左右皆散，都督李穆下馬，以策抶泰背罵曰：「籠東軍士！", literal: "Yuwen Tai fell; Eastern Wei soldiers caught up; his attendants scattered; Commander Li Mu dismounted, whipped Yuwen Tai's back with his riding crop, and shouted, \"Soldiers of Longdong!", idiomatic: "Yuwen Tai fell. Eastern Wei soldiers closed in; his attendants scattered. Commander Li Mu dismounted, whipped Yuwen Tai's back with his crop, and roared, \"Soldiers of Longdong!" },
  { zh: "爾曹主何在，而獨留此？", literal: "Where is your master, that you linger here alone?", idiomatic: "Where is your master, that you linger here alone?" },
  { zh: "」追者不疑其貴人，捨之而過。", literal: "\" The pursuers did not suspect he was a man of rank and let him pass.", idiomatic: "\" The pursuers took him for a common soldier and let him pass." },
  { zh: "穆以馬授泰，與之俱逸。", literal: "Mu gave Yuwen Tai his horse, and both escaped together.", idiomatic: "Mu gave Yuwen Tai his horse, and both escaped together." },
  { zh: "魏兵復振，擊東魏兵，大破之，東魏兵北走。", literal: "The Western Wei army rallied, struck the Eastern Wei army, and routed them; the Eastern Wei army fled north.", idiomatic: "The Western Wei army rallied, struck the Eastern Wei army, and broke them; the Eastern Wei men fled north." },
  { zh: "京兆忠武公高敖曹，意輕泰，建旗蓋以陵陳，魏人盡銳攻之，一軍皆沒，敖曹單騎走投河陽南城。", literal: "Gao Aocao, Duke of Loyal Martial of Jingzhao, despised Yuwen Tai and raised banners and canopy to dominate the line; the Western Wei threw every elite at him, his whole command was destroyed, and Aocao fled alone toward the south gate of Heyang.", idiomatic: "Gao Aocao, Duke of Loyal Martial of Jingzhao, despised Yuwen Tai and raised banners and canopy to lord over the line. Western Wei threw every elite at him until his whole command was gone; Aocao fled alone toward Heyang's south gate." },
  { zh: "守將北豫州刺史高永樂，歡之從祖兄子也，與敖曹有怨，閉門不受。", literal: "The garrison commander, Northern Yu province inspector Gao Yongle—a cousin's son of Gao Huan—bore a grudge against Aocao and shut the gate against him.", idiomatic: "The garrison commander, Northern Yu inspector Gao Yongle—a cousin's son of Gao Huan—bore a grudge against Aocao and shut the gate against him." },
  { zh: "敖曹仰呼求繩，不得，拔刀穿闔未徹而追兵至。", literal: "Aocao shouted upward for a rope; none came; he drew his sword to pierce the gate before it gave way, and the pursuers arrived.", idiomatic: "Aocao shouted up for a rope; none came. He drew his sword to pierce the gate before it gave way, and the pursuers were upon him." },
  { zh: "敖曹伏橋下，追者見其從奴持金帶，問敖曹所在，奴指示之。", literal: "Aocao hid under the bridge; pursuers saw his attendant holding a gold belt, asked where Aocao was, and the slave pointed him out.", idiomatic: "Aocao hid under the bridge. Pursuers saw his attendant with a gold belt, asked where Aocao was, and the slave pointed him out." },
  { zh: "敖曹知不免，奮頭曰：「來！", literal: "Knowing he could not escape, Aocao raised his head and said, \"Come!", idiomatic: "Knowing he could not escape, Aocao raised his head and said, \"Come!" },
  { zh: "與汝開國公。", literal: "I'll make you a Duke Who Founded a State.", idiomatic: "I'll make you a Duke Who Founded a State.\"" },
  { zh: "」追者斬其首去。", literal: "\" The pursuers cut off his head and left.", idiomatic: "The pursuers cut off his head and left." },
  { zh: "高歡聞之，如喪肝膽，杖高永樂二百，贈敖曹太師、大司馬、太尉。", literal: "Gao Huan heard of it as if he had lost liver and gall; he had Gao Yongle beaten two hundred strokes and posthumously honored Aocao as Grand Tutor, Grand Marshal, and Grand Commandant.", idiomatic: "Gao Huan heard of it as if he had lost his vitals; he had Gao Yongle beaten two hundred strokes and posthumously honored Aocao as Grand Tutor, Grand Marshal, and Grand Commandant." },
  { zh: "泰賞殺敖曹者布絹萬段，歲歲稍與之，比及周亡，猶未能足。", literal: "Yuwen Tai rewarded Aocao's killer with ten thousand bolts of silk, giving a little more each year; by the fall of Zhou the debt was still not fully paid.", idiomatic: "Yuwen Tai rewarded Aocao's killer with ten thousand bolts of silk, adding a little more each year; by the fall of Zhou the debt was still not fully paid." },
  { zh: "魏又殺東魏西兗州刺史宋顯等，虜甲士萬五千人，赴河死者以萬數。", literal: "Western Wei also killed Eastern Wei's western Yan province inspector Song Xian and others, took fifteen thousand armored soldiers prisoner, and tens of thousands drowned in the river.", idiomatic: "Western Wei also killed Eastern Wei's western Yan inspector Song Xian and others, took fifteen thousand armored men prisoner, and tens of thousands drowned in the river." },
  { zh: "初，歡以-{万俟}-普尊老，特禮之，嘗親扶上馬。", literal: "Earlier, because Moqi Puzun was old, Gao Huan had shown him special courtesy and once helped him mount his horse in person.", idiomatic: "Earlier, because Moqi Puzun was old, Gao Huan had shown him special courtesy and once helped him mount in person." },
  { zh: "其子洛免冠稽首曰：「願出死力以報深恩。", literal: "His son Luo bared his head and kowtowed, saying, \"I wish to give my life's strength to repay your deep grace.", idiomatic: "His son Luo bared his head and kowtowed, saying, \"I wish to give my life's strength to repay your deep grace.\"" },
  { zh: "」及邙山之戰，諸軍北度橋，洛獨勒兵不動，謂魏人曰：「-{万俟}-受洛干在此，能來可來也！", literal: "\" At the battle of Mangshan, as the armies crossed the bridge north, Luo alone held his troops motionless and called to the Western Wei men, \"Moqi Shouluogan is here—if you can come, come!", idiomatic: "At Mangshan, as the armies crossed the bridge north, Luo alone held his troops and called to Western Wei, \"Moqi Shouluogan is here—if you dare, come!" },
  { zh: "」魏人畏之而去，歡名其所營地為回洛。", literal: "\" The Western Wei men feared him and withdrew; Gao Huan named his camp ground Huiluo.", idiomatic: "\" Western Wei feared him and withdrew; Gao Huan named his camp ground Huiluo." },
  { zh: "是日，東、西魏置陳既大，首尾懸遠，從旦至未，戰數十合，氛霧四塞，莫能相知。", literal: "That day the Eastern and Western Wei battle lines were vast, head and tail far apart; from dawn to the wei hour they fought dozens of engagements; mist filled every quarter and neither side could tell friend from foe.", idiomatic: "That day the Eastern and Western Wei lines were vast, head and tail far apart; from dawn to the wei hour they fought dozens of rounds; mist filled every quarter and neither side could tell friend from foe." },
  { zh: "魏獨孤信、李遠居右，趙貴、怡峰居左，戰並不利；", literal: "Western Wei's Dugu Xin and Li Yuan held the right; Zhao Gui and Yi Feng the left—both wings fought badly;", idiomatic: "Dugu Xin and Li Yuan held Western Wei's right; Zhao Gui and Yi Feng the left—both wings were beaten;" },
  { zh: "又未知魏主及丞相泰所在，皆棄其卒先歸。", literal: "they also did not know where the Western Wei emperor and Chancellor Yuwen Tai were, and all abandoned their troops and fled first.", idiomatic: "they also did not know where the Western Wei emperor and Yuwen Tai were, and all abandoned their men and fled first." },
  { zh: "開府儀同三司李虎、念賢等為後軍，見信等退，即與俱去。", literal: "Kaifu Yitong Sansi Li Hu, Nian Xian, and others formed the rear; seeing Xin and the rest retreat, they withdrew with them.", idiomatic: "Li Hu, Nian Xian, and others formed the rear; seeing Xin and the rest retreat, they withdrew with them." },
  { zh: "泰由是燒營而歸，留儀同三司長孫子彥守金墉。", literal: "Yuwen Tai therefore burned his camp and withdrew, leaving Yitong Sansi Changsun Ziyan to hold Jinyong.", idiomatic: "Yuwen Tai burned his camp and withdrew, leaving Changsun Ziyan to hold Jinyong." },
  { zh: "王思政下馬，舉長槊左右橫擊，一舉輒踣數人。", literal: "Wang Sizheng dismounted, raised his long spear, and struck left and right across the line; each blow knocked down several men.", idiomatic: "Wang Sizheng dismounted, raised his long spear, and struck left and right; each sweep knocked down several men." },
  { zh: "陷陳既深，從者盡死，思政被重創，悶絕。", literal: "He had driven deep into the enemy line; his followers were all dead; Sizheng took grave wounds and fainted.", idiomatic: "He had driven deep into the enemy line; his followers were all dead; Sizheng took grave wounds and fainted." },
  { zh: "會日暮，敵亦收兵。", literal: "At sunset the enemy also withdrew.", idiomatic: "At sunset the enemy also withdrew." },
  { zh: "思政每戰常著破衣弊甲，敵不知其將帥，故得免。", literal: "Sizheng always fought in worn clothes and poor armor, so the enemy did not know he was a general and he escaped.", idiomatic: "Sizheng always fought in worn clothes and poor armor, so the enemy did not know he was a general and he escaped." },
  { zh: "帳下督雷五安於戰處哭求思政，會其已蘇，割衣裹創，扶思政上馬。", literal: "His aide Lei Wu'an wept and searched for Sizheng on the field; finding him already awake, he cut cloth to bind his wounds and helped Sizheng mount.", idiomatic: "His aide Lei Wu'an wept and searched for Sizheng on the field; finding him already awake, he cut cloth to bind his wounds and helped him mount." },
  { zh: "夜久，始得還營。", literal: "Late into the night he finally returned to camp.", idiomatic: "Late into the night he finally returned to camp." },
  { zh: "平東將軍蔡祐下馬步鬥，左右勸乘馬以備倉猝，祐怒曰：「丞相愛我如子，今日豈惜生乎！", literal: "General Who Pacifies the East Cai You dismounted to fight on foot; his attendants urged him to mount against sudden danger; You angrily said, \"The chancellor loves me like a son—would I spare my life today!", idiomatic: "Cai You, General Who Pacifies the East, dismounted to fight on foot. His men urged him to mount against sudden danger; You snapped, \"The chancellor loves me like a son—would I spare my life today!" },
  { zh: "」帥左右十餘人合聲大呼，擊東魏兵，殺傷甚眾。", literal: "\" He led a dozen men in a single shout, struck the Eastern Wei army, and killed and wounded many.", idiomatic: "\" He led a dozen men in one shout, struck the Eastern Wei line, and killed and wounded many." },
  { zh: "東魏人圍之十餘重，祐彎弓持滿，四面拒之。", literal: "Eastern Wei surrounded him more than ten deep; You drew his bow full and held them off on every side.", idiomatic: "Eastern Wei surrounded him more than ten deep; You drew his bow full and held them off on every side." },
  { zh: "東魏人募厚甲長刀者直進取之，去祐可三十步，左右勸射之，祐曰：「吾曹之命，在此一矢，豈可虛發！", literal: "Eastern Wei recruited men in heavy armor with long blades to advance straight on him; they were thirty paces away when his men urged him to shoot; You said, \"Our lives hang on this one arrow—how can I loose it in vain!", idiomatic: "Eastern Wei sent heavy-armored men with long blades straight at him. At thirty paces his men urged him to shoot; You said, \"Our lives hang on this one arrow—how can I waste it!" },
  { zh: "」將至十步，祐乃射之，應弦而倒，東魏兵稍卻，祐徐引還。", literal: "\" When they were ten paces away, You shot; the man fell at the bowstring's sound; the Eastern Wei troops fell back slightly, and You withdrew at leisure.", idiomatic: "\" At ten paces he shot; the man fell at the bowstring's sound; Eastern Wei fell back a little, and You withdrew at leisure." },
  { zh: "魏主至恆農，守將已棄城走，所虜降卒在恆農者相與閉門拒守，丞相泰攻拔之，誅其魁首數百人。", literal: "The Western Wei emperor reached Hengnong; the garrison commander had already abandoned the city and fled; captured Eastern Wei troops at Hengnong together shut the gates to resist; Chancellor Yuwen Tai stormed the city, took it, and executed several hundred ringleaders.", idiomatic: "The Western Wei emperor reached Hengnong; the garrison commander had already fled. Captured Eastern Wei troops there shut the gates to resist; Yuwen Tai stormed the city, took it, and executed several hundred ringleaders." },
  { zh: "蔡祐追及泰於恆農，夜，見泰，泰曰：「承先，爾來，吾無憂矣。", literal: "Cai You caught up with Yuwen Tai at Hengnong; by night he saw Tai; Tai said, \"Chenxian, you have come—I have no more worries.", idiomatic: "Cai You caught Yuwen Tai at Hengnong. That night he came before him; Tai said, \"Chenxian, you have come—I have no more worries.\"" },
  { zh: "」泰驚不得寢，枕祐股，然後安。", literal: "\" Tai was too shaken to sleep until he rested his head on You's thigh; only then was he at peace.", idiomatic: "Tai was too shaken to sleep until he rested his head on You's thigh; only then could he rest." },
  { zh: "祐每從泰戰，常為士卒先。", literal: "Whenever You followed Yuwen Tai into battle, he always led the soldiers first.", idiomatic: "Whenever You followed Yuwen Tai into battle, he always led the soldiers first." },
  { zh: "戰還，諸將皆爭功，祐終無所言。", literal: "After battle the generals all contended for merit; You never spoke.", idiomatic: "After battle the generals all contended for merit; You never spoke." },
  { zh: "泰每歎曰：「承先口不言勳，我當代其論敘。", literal: "Yuwen Tai often sighed, \"Chenxian's mouth never speaks of merit—I must speak his deeds for him.", idiomatic: "Yuwen Tai often sighed, \"Chenxian never speaks of his merit—I must speak it for him.\"" },
  { zh: "」泰留王思政鎮恆農，除侍中、東道行台。", literal: "\" Yuwen Tai left Wang Sizheng to garrison Hengnong and appointed him Attendant-in-Ordinary and Eastern Route Grand Commissioner.", idiomatic: "Yuwen Tai left Wang Sizheng to garrison Hengnong and made him Attendant-in-Ordinary and Eastern Route Grand Commissioner." },
  { zh: "魏之東伐也，關中留守兵少，前後所虜東魏士卒散在民間，聞魏兵敗，謀作亂。", literal: "When Western Wei marched east, few troops remained in Guanzhong; Eastern Wei soldiers captured earlier and scattered among the people heard that Western Wei had been defeated and plotted rebellion.", idiomatic: "When Western Wei marched east, few troops remained in Guanzhong; Eastern Wei prisoners scattered among the people heard Western Wei had been beaten and plotted rebellion." },
  { zh: "李虎等至長安，計無所出，與太尉王盟、僕射周惠達等奉太子欽出屯渭北。", literal: "Li Hu and the others reached Chang'an with no plan; with Grand Commandant Wang Meng, Vice Director Zhou Huida, and the rest they escorted Crown Prince Qin to camp north of the Wei River.", idiomatic: "Li Hu and the others reached Chang'an at a loss; with Grand Commandant Wang Meng, Vice Director Zhou Huida, and the rest they escorted Crown Prince Qin to camp north of the Wei River." },
  { zh: "百姓互相剽掠，關中大擾。", literal: "The common people plundered one another; Guanzhong was in great turmoil.", idiomatic: "The people plundered one another; Guanzhong was in turmoil." },
  { zh: "於是沙苑所虜東魏都督趙青雀、雍州民於伏德等遂反，青雀據長安子城，伏德保咸陽，與咸陽太守慕容思慶各收降卒以拒還兵。", literal: "Then Zhao Qingque, an Eastern Wei commander captured at Shaya, and Yu Fude, a man of Yong province, rebelled; Qingque held Chang'an's inner city, Fude held Xianyang, and with Xianyang governor Murong Siqing each gathered surrendered troops to resist the returning army.", idiomatic: "Then Zhao Qingque, an Eastern Wei commander taken at Shaya, and Yu Fude of Yong province rebelled. Qingque held Chang'an's inner city, Fude held Xianyang, and with Xianyang governor Murong Siqing they gathered surrendered troops to block the returning army." },
  { zh: "長安大城民相帥以拒青雀，日與之戰。", literal: "The people of Chang'an's outer city together led resistance to Qingque and fought him daily.", idiomatic: "The people of Chang'an's outer city banded together to resist Qingque and fought him daily." },
  { zh: "大都督侯莫陳順擊賊，屢破之，賊不敢出。", literal: "Grand Commander Houmochen Shun attacked the rebels, repeatedly defeated them, and the rebels dared not come out.", idiomatic: "Grand Commander Houmochen Shun attacked the rebels, beat them again and again, and they dared not come out." },
  { zh: "順，崇之兄也。", literal: "Shun was the elder brother of Chong.", idiomatic: "Shun was the elder brother of Chong." },
  { zh: "扶風公王羆鎮河東，大開城門，悉召軍士謂曰：「今聞大軍失利，青雀作亂，諸人莫有固志。", literal: "Duke of Fufeng Wang Pi garrisoned Hedong, opened the city gates wide, and summoned all the soldiers, saying, \"Word has come that the great army was defeated and Qingque has risen in revolt—none of you should lose heart.", idiomatic: "Wang Pi, Duke of Fufeng, held Hedong. He threw open the gates, called every soldier, and said, \"Word has come that the great army was beaten and Qingque has risen—none of you should lose heart." },
  { zh: "王羆受委於此，以死報恩。", literal: "Wang Pi has been entrusted here and will repay grace with his death.", idiomatic: "Wang Pi has been entrusted here and will repay that grace with his life." },
  { zh: "有能同心者可共固守；", literal: "Whoever can stand together may hold the city with me;", idiomatic: "Whoever will stand with me, hold the city;" },
  { zh: "必恐城陷，任自出城。", literal: "whoever fears the city will fall may leave whenever he wishes.", idiomatic: "whoever fears the city will fall may leave whenever he wishes.\"" },
  { zh: "」眾感其言，皆無異志。", literal: "\" The crowd was moved by his words and none wavered.", idiomatic: "The men were moved by his words and none wavered." },
  { zh: "魏主留閿鄉。", literal: "The Western Wei emperor remained at Wen township.", idiomatic: "The Western Wei emperor remained at Wen township." },
  { zh: "丞相泰以士馬疲弊，不可速進，且謂青雀等烏合，不能為患，曰：「我至長安，以輕騎臨之，必當面縛。", literal: "Chancellor Yuwen Tai, because men and horses were worn out and could not advance quickly, and because he thought Qingque and the rest were a rabble that could do no harm, said, \"When I reach Chang'an I will ride against them with light cavalry—they will surely be bound before me.", idiomatic: "Yuwen Tai, finding men and horses exhausted and unable to march fast, thought Qingque and the rest a rabble that could do no harm. He said, \"When I reach Chang'an I will ride against them with light cavalry—they will be bound before me.\"" },
  { zh: "」通直散騎常侍吳郡陸通諫曰：「賊逆謀久定，必無遷善之心。", literal: "\" Direct Cavalier Attendant-in-Ordinary Lu Tong of Wu commandery remonstrated, \"The rebels' plot has long been fixed—they surely have no mind to mend their ways.", idiomatic: "Direct Cavalier Attendant-in-Ordinary Lu Tong of Wu remonstrated, \"The rebels' plot is long fixed—they have no mind to mend their ways." },
  { zh: "蜂蠆有毒，安可輕也！", literal: "Wasps and scorpions have poison—how can they be treated lightly!", idiomatic: "Wasps and scorpions have poison—how can they be treated lightly!" },
  { zh: "且賊詐言東寇將至，今若以輕騎臨之，百姓謂為信然，益當驚擾。", literal: "Moreover the rebels falsely say an eastern enemy is coming; if you now ride against them with light cavalry, the people will take it for truth and grow more alarmed.", idiomatic: "Moreover they falsely claim an eastern enemy is coming; if you ride against them with light cavalry, the people will believe it and grow more alarmed." },
  { zh: "今軍雖疲弊，精銳尚多。", literal: "The army is weary, but elite troops remain in plenty.", idiomatic: "The army is weary, but plenty of elite troops remain." },
  { zh: "以明公之威，總大軍以臨之，何憂不克！", literal: "With your lordship's prestige, lead the whole army against them—why fear you cannot overcome them!", idiomatic: "With your prestige, lead the whole army against them—why fear you cannot break them!" },
  { zh: "」泰從之，引兵西入。", literal: "\" Yuwen Tai followed his advice and led his army west.", idiomatic: "Yuwen Tai took his advice and led his army west." },
  { zh: "父老見泰至，莫不悲喜，士女相賀。", literal: "When the elders saw Yuwen Tai arrive, none failed to weep for joy; men and women congratulated one another.", idiomatic: "When the elders saw Yuwen Tai arrive, none failed to weep for joy; men and women congratulated one another." },
  { zh: "華州刺史宇文導引兵襲咸陽，斬思慶，擒伏德。", literal: "Hua province inspector Yuwen Dao led troops to strike Xianyang, beheaded Siqing, and captured Fude.", idiomatic: "Hua inspector Yuwen Dao struck Xianyang, beheaded Siqing, and captured Fude." },
  { zh: "南度渭，與泰會攻青雀，破之。", literal: "He crossed the Wei southward, joined Yuwen Tai, and together attacked Qingque and broke him.", idiomatic: "He crossed the Wei southward, joined Yuwen Tai, and together broke Qingque." },
  { zh: "太保梁景睿以疾留長安，與青雀通謀，泰殺之。", literal: "Grand Guardian Liang Jingrui, ill and left at Chang'an, conspired with Qingque; Yuwen Tai executed him.", idiomatic: "Grand Guardian Liang Jingrui, ill and left at Chang'an, had conspired with Qingque; Yuwen Tai executed him." },
  { zh: "東魏太師歡自晉陽將七千騎至孟津，未濟，聞魏師已循，遂濟河，遣別將追魏師至崤，不及而還。", literal: "Eastern Wei Grand Mentor Gao Huan himself led seven thousand horsemen from Jinyang to Meng Ford; before he crossed, he heard the Western Wei army had already withdrawn, crossed the river, sent a detached force in pursuit to the Xiao Mountains, could not overtake them, and returned.", idiomatic: "Gao Huan himself led seven thousand horsemen from Jinyang to Meng Ford. Before he crossed, he heard the Western Wei army had already withdrawn; he crossed, sent a detachment in pursuit to the Xiao Mountains, could not overtake them, and returned." },
  { zh: "歡攻金墉，長孫子彥棄城走，焚城中室屋俱盡，歡毀金墉而還。", literal: "Gao Huan attacked Jinyong; Changsun Ziyan abandoned the city and fled, burning every building within; Huan destroyed Jinyong and returned.", idiomatic: "Gao Huan attacked Jinyong; Changsun Ziyan abandoned the city and fled, burning every building within; Huan razed Jinyong and returned." },
  { zh: "東魏之遷鄴也，主客郎中裴讓之留洛陽。", literal: "When Eastern Wei moved the capital to Ye, Master of Guests Pei Rangzhi remained at Luoyang.", idiomatic: "When Eastern Wei moved the capital to Ye, Master of Guests Pei Rangzhi remained at Luoyang." },
  { zh: "獨孤信之敗也，讓之弟諏之隨丞相泰入關，為大行台倉曹郎中。", literal: "When Dugu Xin was defeated, Rangzhi's younger brother Xunzhi followed Chancellor Yuwen Tai into Guanzhong and served as Grand Commissioner's clerk for granaries.", idiomatic: "When Dugu Xin was defeated, Rangzhi's younger brother Xunzhi followed Yuwen Tai into Guanzhong and served as the Grand Commissioner's granary clerk." },
  { zh: "歡囚讓之兄弟五人，讓之曰：「昔諸葛亮兄弟，事吳、蜀各盡其心，況讓之老母在此，不忠不孝，必不為也。", literal: "Gao Huan imprisoned all five Rangzhi brothers; Rangzhi said, \"In old times Zhuge Liang's brothers served Wu and Shu each with all their hearts; moreover Rangzhi's old mother is here—disloyal and unfilial, they surely will not do it.", idiomatic: "Gao Huan imprisoned all five Rangzhi brothers. Rangzhi said, \"In old times the Zhuge brothers served Wu and Shu each with all their hearts; and my old mother is here—disloyal and unfilial, we surely will not do it." },
  { zh: "明公推誠待物，物亦歸心；", literal: "My lord treats men with sincere trust, and men return their hearts;", idiomatic: "My lord treats men with sincere trust, and men return their hearts;" },
  { zh: "若用猜忌，去霸業遠矣。", literal: "if you use suspicion instead, you are far from hegemony.", idiomatic: "use suspicion instead, and you are far from hegemony.\"" },
  { zh: "」歡皆釋之。", literal: "\" Gao Huan released them all.", idiomatic: "Gao Huan released them all." },
  { zh: "九月，魏主入長安，丞相泰還屯華州。", literal: "In the ninth month the Western Wei emperor entered Chang'an; Chancellor Yuwen Tai returned to camp at Huazhou.", idiomatic: "In the ninth month the Western Wei emperor entered Chang'an; Yuwen Tai returned to camp at Huazhou." },
  { zh: "東魏大都督賀拔仁擊邢磨納、盧仲禮等，平之。", literal: "Eastern Wei Grand Commander Heluoba Ren attacked Xing Monai, Lu Zhongli, and the rest and pacified them.", idiomatic: "Eastern Wei Grand Commander Heluoba Ren attacked Xing Monai, Lu Zhongli, and the rest and pacified them." },
  { zh: "盧景裕本儒生，太師歡釋之，召館於家，使教諸子。", literal: "Lu Jingyu was originally a Confucian scholar; Grand Mentor Gao Huan released him and had him lodge at home to teach his sons.", idiomatic: "Lu Jingyu was originally a Confucian scholar; Gao Huan released him, took him into his household, and had him teach his sons." },
  { zh: "景裕講論精微，難者或相詆訶，大聲厲色，言至不遜，而景裕神采儼然，風調如一，從容往復，無際可尋。", literal: "Jingyu's discourse was subtle; when challengers sometimes reviled him with loud voice and harsh color, speech even to insolence, Jingyu's bearing remained grave, his tone unchanged, and he answered at ease back and forth with no seam to find.", idiomatic: "Jingyu's discourse was subtle; when challengers sometimes reviled him with raised voice and harsh color, even to insolence, Jingyu's bearing stayed grave, his tone unchanged, and he answered at ease with no seam to find." },
  { zh: "性清靜，歷官屢有進退，無得失之色；", literal: "By nature he was quiet; through repeated promotions and demotions in office he showed no sign of gain or loss;", idiomatic: "By nature he was quiet; through repeated promotions and demotions he showed no sign of gain or loss;" },
  { zh: "弊衣粗食，恬然自安，終日端嚴，如對賓客。", literal: "in worn clothes and coarse food he was content, all day upright as if facing guests.", idiomatic: "in worn clothes and coarse food he was content, all day upright as if facing guests." },
  { zh: "冬，十月，魏歸高敖曹、竇泰、莫多婁貸文之首於東魏。", literal: "In winter, the tenth month, Western Wei returned the heads of Gao Aocao, Dou Tai, and Mo Duo Lou Daiwen to Eastern Wei.", idiomatic: "In winter, the tenth month, Western Wei returned the heads of Gao Aocao, Dou Tai, and Mo Duo Lou Daiwen to Eastern Wei." },
  { zh: "散騎常侍劉孝儀等聘於東魏。", literal: "Cavalier Attendant-in-Ordinary Liu Xiaoyi and others went on a friendly mission to Eastern Wei.", idiomatic: "Cavalier Attendant-in-Ordinary Liu Xiaoyi and others went on a friendly mission to Eastern Wei." },
  { zh: "十二月，魏是雲寶襲洛陽，東魏洛州刺史王元軌棄城走。", literal: "In the twelfth month, Western Wei's Shi Yunbao raided Luoyang; Eastern Wei's Luo province inspector Wang Yuan Gui abandoned the city and fled.", idiomatic: "In the twelfth month, Western Wei's Shi Yunbao raided Luoyang; Eastern Wei's Luo inspector Wang Yuan Gui abandoned the city and fled." },
  { zh: "都督趙剛襲廣州，拔之。", literal: "Commander Zhao Gang raided Guang province and took it.", idiomatic: "Commander Zhao Gang raided Guang province and took it." },
  { zh: "於是自襄、廣已西城鎮復為魏。", literal: "From Xiang and Guang westward the frontier garrisons thus returned to Western Wei.", idiomatic: "From Xiang and Guang westward the frontier garrisons thus returned to Western Wei." },
  { zh: "魏自正光以後，四方多事，民避賦役，多為僧尼，至二百萬人，寺有三萬餘區。", literal: "Since the Zhenguang era Western Wei had been beset on every side; to escape taxes and corvée many became monks and nuns—up to two million persons, with more than thirty thousand monasteries.", idiomatic: "Since the Zhenguang era Western Wei had been beset on every side; to escape taxes and corvée many became monks and nuns—up to two million persons and more than thirty thousand monasteries." },
  { zh: "至是，東魏始詔「牧守、令長擅立寺者，計其功庸，以枉法論。", literal: "Now Eastern Wei for the first time decreed, \"Pasture chiefs and district magistrates who on their own authority establish monasteries shall have their merit reckoned and be punished as bending the law.", idiomatic: "Now Eastern Wei for the first time decreed that pasture chiefs and district magistrates who established monasteries on their own authority would have their merit reckoned and be punished for bending the law." },
  { zh: "初，魏伊川土豪李長壽為防蠻都督，積功至北華州刺史。", literal: "Earlier, Li Changshou, a powerful man of the Yi River in Western Wei, had been Defense Commander against the Man and through accumulated merit rose to Northern Hua province inspector.", idiomatic: "Earlier Li Changshou, a powerful man of the Yi River in Western Wei, had been Defense Commander against the Man and through merit rose to Northern Hua inspector." },
  { zh: "孝武帝西遷，長壽帥其徒拒東魏，魏以長壽為廣州刺史。", literal: "When Emperor Xiaowu moved west, Changshou led his followers to resist Eastern Wei; Western Wei made Changshou Guang province inspector.", idiomatic: "When Emperor Xiaowu moved west, Changshou led his followers against Eastern Wei; Western Wei made him Guang inspector." },
  { zh: "侯景攻拔其壁，殺之。", literal: "Hou Jing stormed his fort, killed him.", idiomatic: "Hou Jing stormed his fort and killed him." },
  { zh: "其子延孫復收集父兵以拒東魏，魏之貴臣廣陵王欣、錄尚書長孫稚等皆攜家往依之，延孫資遣衛送，使達關中。", literal: "His son Yansun gathered his father's troops again to resist Eastern Wei; Western Wei's great ministers, the Prince of Guangling Xin and Recorder of the Masters of Writing Changsun Zhi and others, all brought their families to rely on him; Yansun supplied and escorted them until they reached Guanzhong.", idiomatic: "His son Yansun gathered his father's troops again to resist Eastern Wei; Western Wei's great ministers—the Prince of Guangling Xin, Recorder Changsun Zhi, and others—all brought their families to him; Yansun supplied and escorted them to Guanzhong." },
  { zh: "東魏高歡患之，數遣兵攻延孫，不能克。", literal: "Eastern Wei's Gao Huan was troubled by this and repeatedly sent troops against Yansun but could not overcome him.", idiomatic: "Gao Huan was troubled by this and repeatedly sent troops against Yansun but could not overcome him." },
  { zh: "魏以延孫為京南行台、節度河南諸軍事、廣州刺史。", literal: "Western Wei made Yansun Southern Capital Route Grand Commissioner, commander of all military affairs south of the river in Henan, and Guang province inspector.", idiomatic: "Western Wei made Yansun Southern Capital Route Grand Commissioner, commander of Henan military affairs south of the river, and Guang inspector." },
  { zh: "延孫以澄清伊、洛為己任，魏以延孫兵少，更以長壽之婿京兆韋法保為東洛州刺史，配兵數百以助之。", literal: "Yansun took clearing the Yi and Luo as his charge; Western Wei, because Yansun had few troops, further made Changshou's son-in-law Wei Fabao of Jingzhao Eastern Luo inspector and assigned him several hundred soldiers to assist.", idiomatic: "Yansun took clearing the Yi and Luo as his charge; Western Wei, finding him short of troops, further made Changshou's son-in-law Wei Fabao of Jingzhao Eastern Luo inspector and gave him several hundred men to assist." },
  { zh: "法保名祐，以字行，既至，與延孫連兵置柵於伏流。", literal: "Fabao's given name was You; he went by his style; when he arrived he joined Yansun in linking camps at Fuliou.", idiomatic: "Fabao's given name was You; he went by his style. When he arrived he joined Yansun in linking camps at Fuliou." },
  { zh: "獨孤信之入洛陽也，欲繕修宮室，使外兵郎中天水權景宣帥徒兵三千出采運。", literal: "When Dugu Xin entered Luoyang he wished to repair the palaces and sent Outer Troops Gentleman Quan Jingxuan of Tianshui to lead three thousand laborers out to gather transport timber.", idiomatic: "When Dugu Xin entered Luoyang he wished to repair the palaces and sent Outer Troops Gentleman Quan Jingxuan of Tianshui to lead three thousand laborers out for timber." },
  { zh: "會東魏兵至，河南皆叛，景宣間道西走，與李延孫相會，攻孔城，拔之，洛陽以南尋亦西附。", literal: "Eastern Wei troops arrived; all south of the river rebelled; Jingxuan took a hidden path west, met Yansun, attacked Kong city, took it, and south of Luoyang soon submitted westward again.", idiomatic: "Eastern Wei troops arrived; all south of the river rebelled. Jingxuan took a hidden path west, met Yansun, attacked Kong city and took it; south of Luoyang soon submitted westward again." },
  { zh: "丞相泰即留景宣守張白塢，節度東南諸軍應關西者。", literal: "Chancellor Yuwen Tai at once left Jingxuan to hold Zhangbai Stockade and command southeastern military affairs responding to Guanxi.", idiomatic: "Yuwen Tai left Jingxuan to hold Zhangbai Stockade and command southeastern forces answering Guanxi." },
  { zh: "是歲，延孫為其長史楊伯蘭所殺，韋法保即引兵據延孫之柵。", literal: "That year Yansun was killed by his chief clerk Yang Bolan; Wei Fabao at once led troops to hold Yansun's stockade.", idiomatic: "That year Yansun was killed by his chief clerk Yang Bolan; Wei Fabao at once led troops to hold Yansun's stockade." },
  { zh: "東魏將段琛等據宜陽，遣陽州刺史牛道恆誘魏邊民。", literal: "Eastern Wei generals Duan Chen and others held Yiyang and sent Yang province inspector Niu Daoheng to entice Western Wei border people.", idiomatic: "Eastern Wei generals Duan Chen and others held Yiyang and sent Yang inspector Niu Daoheng to entice Western Wei border people." },
  { zh: "魏南兗州刺史韋孝寬患之，乃詐為道恆與孝寬書，論歸款之意，使諜人遺之於琛營，琛果疑道恆。", literal: "Southern Yan province inspector Wei Xiaokuan was troubled by this; he forged a letter in Daoheng's name to Xiaokuan discussing surrender, and had a spy leave it in Chen's camp; Chen indeed suspected Daoheng.", idiomatic: "Southern Yan inspector Wei Xiaokuan was troubled by this. He forged a letter in Daoheng's name to Xiaokuan discussing surrender and had a spy leave it in Chen's camp; Chen indeed suspected Daoheng." },
  { zh: "孝寬乘其猜阻，出兵襲之，擒道恆及琛，崤、澠遂清。", literal: "Xiaokuan exploited their mutual suspicion, sent troops to strike, captured Daoheng and Chen, and the Xiao and Mian routes were cleared.", idiomatic: "Xiaokuan exploited their suspicion, struck, captured Daoheng and Chen, and the Xiao and Mian routes were cleared." },
  { zh: "東道行台王思政以玉壁險要，請築城，自恆農徙鎮之，詔加都督汾、晉、并州諸軍事、并州刺史，行台如故。", literal: "Eastern Route Grand Commissioner Wang Sizheng, because Yubi was strategically vital, asked to build a fortress; he moved his garrison from Hengnong; he was further made commander of Fen, Jin, and Bing military affairs and Bing province inspector, his Grand Commission unchanged.", idiomatic: "Eastern Route Grand Commissioner Wang Sizheng, finding Yubi strategically vital, asked to build a fortress and moved his garrison from Hengnong; he was further made commander of Fen, Jin, and Bing military affairs and Bing inspector, his Grand Commission unchanged." },
  { zh: "東魏以高澄攝吏部尚書，始改崔亮年勞之制，銓擢賢能；", literal: "Eastern Wei put Gao Cheng in charge of the Ministry of Personnel and for the first time changed Cui Liang's seniority system, selecting and promoting the able;", idiomatic: "Eastern Wei put Gao Cheng in charge of the Ministry of Personnel, for the first time changed Cui Liang's seniority system, and selected and promoted the able;" },
  { zh: "又沙汰尚書郎，妙選人地以充之。", literal: "they also sifted Masters of Writing gentlemen, choosing men of fine talent and background to fill the posts.", idiomatic: "they also sifted Masters of Writing posts, choosing men of fine talent and background to fill them." },
  { zh: "凡才名之士，雖未薦擢，皆引致門下，與之遊宴、講論、賦詩，士大夫以是稱之。", literal: "Men of talent and name, though not yet promoted, were all brought to his gate, entertained, debated with, and made to compose poetry; scholar-officials therefore praised him.", idiomatic: "Men of talent and name, though not yet promoted, were all brought to his gate for feasting, debate, and poetry; scholar-officials therefore praised him." },
  { zh: "高祖武皇帝十四大同五年（", literal: "Great Ancestor Emperor Wu, year 15 of the Datong era (", idiomatic: "Emperor Wu of Liang, fifteenth year of Datong (" },
  { zh: "己未，公元五三九年）", literal: "jiwei, 539 CE)", idiomatic: "jiwei, AD 539)" },
  { zh: "春，正月，乙卯，以尚書左僕射蕭淵藻為中衛將軍，丹楊尹何敬容為尚書令，吏部尚書張纘為僕射。", literal: "In spring, the first month, on yimao, Left Vice Director Xiao Yuanzao was made Central Guard General, Danyang governor He Jingrong was made Director of the Masters of Writing, and Ministry of Personnel Director Zhang Zuan was made Vice Director.", idiomatic: "In spring, the first month, on yimao, Left Vice Director Xiao Yuanzao was made Central Guard General, Danyang governor He Jingrong Director of the Masters of Writing, and Ministry of Personnel Director Zhang Zuan Vice Director." },
  { zh: "纘，弘策之子也。", literal: "Zuan was the son of Hongce.", idiomatic: "Zuan was the son of Hongce." },
  { zh: "自晉、宋以來，宰相皆以文義自逸，敬容獨勤簿領，日旰不休，為時俗所嗤鄙。", literal: "Since Jin and Song, chancellors had all taken their ease in literary refinement; Jingrong alone toiled at ledgers, working from dawn unceasing, and was scorned by the fashion of the day.", idiomatic: "Since Jin and Song, chancellors had all taken their ease in literary refinement; Jingrong alone toiled at ledgers from dawn unceasing, and the fashion of the day scorned him." },
  { zh: "自徐勉、周捨既卒，當權要者，外朝則何敬容，內省則朱異。", literal: "After Xu Mian and Zhou She died, those who held power were Jingrong in the outer court and Zhu Yi in the inner.", idiomatic: "After Xu Mian and Zhou She died, power lay with Jingrong in the outer court and Zhu Yi in the inner." },
  { zh: "敬容質愨無文，以綱維為己任；", literal: "Jingrong was plain and without literary polish, taking the framework of rule as his charge;", idiomatic: "Jingrong was plain and without literary polish, taking the framework of rule as his charge;" },
  { zh: "異文華敏洽，曲營世譽。", literal: "Yi was refined, quick, and skilled at currying worldly favor.", idiomatic: "Yi was refined, quick, and skilled at currying worldly favor." },
  { zh: "二人行異而俱得幸於上。", literal: "The two differed in conduct yet both won the sovereign's favor.", idiomatic: "The two differed in conduct yet both won the sovereign's favor." },
  { zh: "異善伺候人主意為阿諛，用事三十年，廣納貨賂，欺罔視聽，遠近莫不忿疾。", literal: "Yi was skilled at watching the sovereign's mind and flattering it; for thirty years he held power, took bribes widely, deceived what the sovereign saw and heard, and near and far alike burned with resentment.", idiomatic: "Yi was skilled at watching the sovereign's mind and flattering it; for thirty years he held power, took bribes widely, deceived what the sovereign saw and heard, and near and far burned with resentment." },
  { zh: "園宅、玩好、飲膳、聲色窮一時之盛。", literal: "His gardens, treasures, food, drink, and music exhausted the splendor of the age.", idiomatic: "His gardens, treasures, food, drink, and music exhausted the splendor of the age." },
  { zh: "每休下，車馬填門，唯王承、王稚及褚翔不往。", literal: "Whenever he left office his gate was jammed with carriages and horses; only Wang Cheng, Wang Zhi, and Chu Xiang did not go.", idiomatic: "Whenever he left office his gate was jammed with carriages; only Wang Cheng, Wang Zhi, and Chu Xiang did not go." },
  { zh: "承、稚，暕之子；", literal: "Cheng and Zhi were sons of Yan;", idiomatic: "Cheng and Zhi were sons of Yan;" },
  { zh: "翔，淵之曾孫也。", literal: "Xiang was a great-grandson of Yuan.", idiomatic: "Xiang was a great-grandson of Yuan." },
  { zh: "丁巳，御史中丞參禮儀事賀琛奏：「南、北二郊及藉田，往還並宜御輦，不復乘輅。", literal: "On dingsi, Censor-in-Chief He Chen, participating in ritual affairs, memorialized, \"The southern and northern suburban sacrifices and the plowing of the sacred field should all use the imperial carriage and no longer ride the ceremonial chariot.", idiomatic: "On dingsi Censor-in-Chief He Chen, participating in ritual affairs, memorialized that the southern and northern suburban sacrifices and the plowing of the sacred field should all use the imperial carriage and no longer the ceremonial chariot." },
  { zh: "」詔從之，祀宗廟仍乘玉輦。", literal: "\" The edict followed this; for ancestral temple sacrifice the jade carriage was still used.", idiomatic: "The edict followed this; for ancestral temple sacrifice the jade carriage was still used." },
  { zh: "琛，瑒之弟子也。", literal: "Chen was a nephew's son of Yang.", idiomatic: "Chen was a nephew's son of Yang." },
  { zh: "辛酉，東魏以尚書令孫騰為司徒。", literal: "On xinyou, Eastern Wei made Director of the Masters of Writing Sun Teng Minister over the Masses.", idiomatic: "On xinyou Eastern Wei made Director of the Masters of Writing Sun Teng Minister over the Masses." },
  { zh: "辛未，上祀南郊。", literal: "On xinwei, the sovereign sacrificed at the southern suburb.", idiomatic: "On xinwei the Liang sovereign sacrificed at the southern suburb." },
  { zh: "魏丞相泰於行台置學，取丞郎、府佐德行明敏者充學生，悉令旦治公務，晚就講習。", literal: "Western Wei Chancellor Yuwen Tai established a school at the Grand Commission, taking Masters of Writing gentlemen and Grand Commission aides of clear conduct and keen mind as students, all to handle public business by day and attend lectures by evening.", idiomatic: "Yuwen Tai established a school at the Grand Commission, taking Masters of Writing gentlemen and Grand Commission aides of clear conduct and keen mind as students to handle public business by day and attend lectures by evening." },
  { zh: "東魏丞相歡，以徐州刺史房謨、廣平太守羊孰、廣宗太守竇瑗、平原太守許惇有政績清能，與諸刺史書，褒稱謨等以勸之。", literal: "Eastern Wei Chancellor Gao Huan, because Xu province inspector Fang Mo, Guangping governor Yang Shu, Guangzong governor Dou Yuan, and Pingyuan governor Xu Dun had achievements in governance and were pure and able, wrote all the inspectors a letter praising Mo and the rest to encourage them.", idiomatic: "Gao Huan, because Xu inspector Fang Mo, Guangping governor Yang Shu, Guangzong governor Dou Yuan, and Pingyuan governor Xu Dun had clean records and ability, wrote all the inspectors praising Mo and the rest to encourage them." },
  { zh: "夏，五月，甲戌，東魏立丞相歡女為皇后；", literal: "In summer, the fifth month, on jiaxu, Eastern Wei installed Chancellor Gao Huan's daughter as empress;", idiomatic: "In summer, the fifth month, on jiaxu Eastern Wei installed Gao Huan's daughter as empress;" },
  { zh: "乙亥，大赦。", literal: "on yihai, a general amnesty was proclaimed.", idiomatic: "on yihai a general amnesty was proclaimed." },
  { zh: "魏以開府儀同三司李弼為司空。", literal: "Western Wei made Kaifu Yitong Sansi Li Bi Minister of Works.", idiomatic: "Western Wei made Li Bi Minister of Works." },
  { zh: "秋，七月，魏以扶風王孚為太尉。", literal: "In autumn, the seventh month, Western Wei made the Prince of Fufeng, Fu, Grand Commandant.", idiomatic: "In autumn, the seventh month, Western Wei made the Prince of Fufeng, Fu, Grand Commandant." },
  { zh: "九月，甲子，東魏發畿內十萬人城鄴，四十日罷。", literal: "In the ninth month, on jiazi, Eastern Wei mobilized one hundred thousand men within the capital circuit to wall Ye; the work ended in forty days.", idiomatic: "In the ninth month, on jiazi Eastern Wei mobilized one hundred thousand men within the capital circuit to wall Ye; the work ended in forty days." },
  { zh: "冬，十月，癸亥，以新宮成，大赦，改元興和。", literal: "In winter, the tenth month, on guihai, because the new palace was completed, a general amnesty was proclaimed and the era name changed to Xinghe.", idiomatic: "In winter, the tenth month, on guihai, because the new palace was completed, a general amnesty was proclaimed and the era name changed to Xinghe." },
  { zh: "魏置紙筆於陽武門外以求得失。", literal: "Western Wei placed brush and paper outside Yangwu Gate to seek the people's gains and losses.", idiomatic: "Western Wei placed brush and paper outside Yangwu Gate to seek the people's gains and losses." },
  { zh: "十一月，乙亥，東魏使散騎常侍王元景、魏收來聘。", literal: "In the eleventh month, on yihai, Eastern Wei sent Cavalier Attendant-in-Ordinary Wang Yuanjing and Wei Shou on a friendly mission.", idiomatic: "In the eleventh month, on yihai Eastern Wei sent Cavalier Attendant-in-Ordinary Wang Yuanjing and Wei Shou on a friendly mission." },
  { zh: "東魏人以《正光歷》浸差，命校書郎李業興更加修正，以甲子為元，號曰《興光歷》，既成，行之。", literal: "Eastern Wei, because the Zhenguang calendar had gradually drifted, ordered collator Li Yexing to revise it further, taking jiazi as origin and naming it the Xingguang calendar; when it was done, it was put in use.", idiomatic: "Eastern Wei, finding the Zhenguang calendar had drifted, ordered collator Li Yexing to revise it, taking jiazi as origin and naming it the Xingguang calendar; when done, it was put in use." },
  { zh: "散騎常侍朱異奏：「頃來置州稍廣，而小大不倫，請分為五品，其位秩高卑，參僚多少，皆以是為差。", literal: "Cavalier Attendant-in-Ordinary Zhu Yi memorialized, \"Recently the establishment of provinces has grown somewhat broad, large and small not in proper order; I ask that they be divided into five grades, with rank, salary, and number of staff all differentiated thereby.", idiomatic: "Cavalier Attendant-in-Ordinary Zhu Yi memorialized, \"Recently provinces have multiplied without proper order; I ask that they be divided into five grades, with rank, salary, and staff all set thereby.\"" },
  { zh: "」詔從之。", literal: "\" The edict followed this.", idiomatic: "The edict followed this." },
  { zh: "於是上品二十州，次品十州，次品八州，次品二十三州，下品二十一州。", literal: "Thus there were twenty provinces of the highest grade, ten of the second, eight of the third, twenty-three of the fourth, and twenty-one of the lowest.", idiomatic: "Thus there were twenty provinces of the highest grade, ten of the second, eight of the third, twenty-three of the fourth, and twenty-one of the lowest." },
  { zh: "時上方事征伐，恢拓境宇，北逾淮、汝，東距彭城，西開牂柯，南平俚洞，建置州郡，紛綸甚眾，故異請分之。", literal: "At the time the sovereign was engaged in campaigns, expanding territory; north beyond the Huai and Ru, east to Pengcheng, west opening Zangke, south pacifying the Li caves—provinces and commanderies were established in profusion, and therefore Yi asked to divide them.", idiomatic: "The sovereign was then campaigning, expanding territory—north beyond the Huai and Ru, east to Pengcheng, west into Zangke, south pacifying the Li caves—provinces and commanderies multiplied in profusion, and therefore Yi asked to grade them." },
  { zh: "其下品皆異國之人來歸附者，徒有州名而無土地，或因荒徼之民所居村落置州及郡縣，刺史守令皆用彼人為之，尚書不能悉領，山川險遠，職貢罕通。", literal: "Those of the lowest grade were all men of foreign states who came to submit; they had only the name of a province and no land, or provinces and districts were set up on villages where frontier people dwelt; inspectors and magistrates were all drawn from those people; the Masters of Writing could not fully oversee them; mountains and rivers were perilous and far, tribute rarely reached.", idiomatic: "The lowest grade were foreigners who had submitted—provinces in name only, without land—or provinces and districts set on frontier villages; inspectors and magistrates were drawn from those peoples; the Masters of Writing could not fully oversee them; mountains were perilous and tribute rarely came." },
  { zh: "五品之外，又有二十餘州不知處所。", literal: "Beyond the five grades there were more than twenty provinces whose location was unknown.", idiomatic: "Beyond the five grades more than twenty provinces had no known location." },
  { zh: "凡一百七州。", literal: "In all there were one hundred seven provinces.", idiomatic: "In all there were one hundred seven provinces." },
  { zh: "又以邊境鎮戍，雖領民不多，欲重其將帥，皆建為郡，或一人領二三郡太守，州郡雖多而戶口日耗矣。", literal: "Moreover, because frontier garrisons, though they ruled few people, wished to weight their commanders, all were made into commanderies, or one man held two or three commanderies as governor; though provinces and commanderies multiplied, households daily dwindled.", idiomatic: "Moreover frontier garrisons, though they ruled few people, were weighted by making them commanderies, or one man held two or three commanderies; provinces and commanderies multiplied while households daily dwindled." },
  { zh: "魏自西遷以來，禮樂散逸，丞相泰命左僕射周惠達、吏部郎中北海唐瑾損益舊章，至是稍備。", literal: "Since Western Wei's move west, ritual and music had scattered; Chancellor Yuwen Tai ordered Left Vice Director Zhou Huida and Ministry of Personnel gentleman Tang Jin of Beihai to trim and augment the old regulations; by now they were somewhat complete.", idiomatic: "Since Western Wei's move west, ritual and music had scattered; Yuwen Tai ordered Zhou Huida and Ministry of Personnel gentleman Tang Jin of Beihai to trim the old regulations; by now they were somewhat complete." },
  { zh: "高祖武皇帝十四大同六年（", literal: "Great Ancestor Emperor Wu, year 16 of the Datong era (", idiomatic: "Emperor Wu of Liang, sixteenth year of Datong (" },
  { zh: "庚申，公元五四零年）", literal: "gengshen, 540 CE)", idiomatic: "gengshen, AD 540)" },
  { zh: "春，正月，壬申，東魏以廣平公庫狄干為太保。", literal: "In spring, the first month, on renshen, Eastern Wei made Duke of Guangping Kudi Gan Grand Guardian.", idiomatic: "In spring, the first month, on renshen Eastern Wei made Kudi Gan, Duke of Guangping, Grand Guardian." },
  { zh: "丁丑，東魏主入新宮，大赦。", literal: "On dingchou, the Eastern Wei ruler entered the new palace and proclaimed a general amnesty.", idiomatic: "On dingchou the Eastern Wei ruler entered the new palace and proclaimed a general amnesty." },
  { zh: "魏扶風王孚卒。", literal: "Western Wei's Prince of Fufeng, Fu, died.", idiomatic: "Prince Fu of Fufeng in Western Wei died." },
  { zh: "二月，己亥，上耕藉田。", literal: "In the second month, on jihai, the emperor plowed the sacred field.", idiomatic: "In the second month, on jihai, the Liang emperor plowed the sacred field." },
  { zh: "魏鑄五銖錢。", literal: "Western Wei cast wuzhu coins.", idiomatic: "Western Wei cast wuzhu coins." },
  { zh: "東魏大行台侯景出三鴉，將復荊州，魏丞相泰遣李弼、獨孤信各將五千騎出武關，景乃還。", literal: "Eastern Wei Grand Mobile Headquarters Hou Jing marched from Sanya intending to recover Jing province; Western Wei Chancellor Tai sent Li Bi and Dugu Xin, each with five thousand horse, out through Wuguan, and Jing withdrew.", idiomatic: "Hou Jing of Eastern Wei marched from Sanya to recover Jing; Yuwen Tai sent Li Bi and Dugu Xin, each with five thousand horse, through Wuguan, and Jing turned back." },
  { zh: "魏文後既為尼，居別宮，悼後猶忌之，乃以其子武都王戊為秦州刺史，使文後隨之官。", literal: "The Wen Empress of Wei had become a nun and lived in a separate palace; the Dowager Empress still resented her and made her son, Prince Wu of Wudu, inspector of Qin, ordering the Wen Empress to go with him to his post.", idiomatic: "Empress Wen had taken the veil and lived apart; Dowager Empress Diao still hated her and sent her son Prince Wu of Wudu to Qin as inspector, making Wen Empress go with him." },
  { zh: "魏主雖限以大計，而恩好不忘，密令養發，有追還之意。", literal: "Though the Wei sovereign was bound by the great plan, he did not forget old affection and secretly ordered her hair to be allowed to grow again, with intent to recall her.", idiomatic: "The Western Wei emperor was held to the great plan but did not forget her; secretly he let her hair grow again, meaning to bring her back." },
  { zh: "會柔然舉國度河南侵，時頗有言柔然以悼後故興師者，帝曰：「豈有興百萬之眾為一女子邪！", literal: "It happened that Rouran crossed the Yellow River in full strength to raid; at the time many said Rouran had raised arms for the dowager empress's sake. The emperor said, \"Would anyone raise a million men for one woman!", idiomatic: "Rouran crossed the river in full strength to raid; many said they came for the dowager empress. The emperor said, \"Who raises a million men for one woman!" },
  { zh: "雖然，致人此言，朕亦何顏以見將帥！", literal: "Still, that men should say this—what face have I to show the generals!", idiomatic: "Yet that such talk should spread—what face have I before my generals!" },
  { zh: "」乃遣中常侍曹寵繼手敕賜文後自盡。", literal: "\" He then sent Palace Attendant Cao Chong with an edict in his own hand ordering the Wen Empress to take her own life.", idiomatic: "\" He sent Palace Attendant Cao Chong with a handwritten edict ordering Wen Empress to die by her own hand." },
  { zh: "文後泣謂寵曰：「願至尊千萬歲，天下康寧，死無恨也！", literal: "The Wen Empress wept and told Chong, \"May His Majesty live ten thousand years and the realm be at peace—I die without regret!", idiomatic: "Wen Empress wept and told Chong, \"May His Majesty live ten thousand years and all under Heaven be at peace—I die without regret!" },
  { zh: "」遂自殺。", literal: "\" She then killed herself.", idiomatic: "\" She then killed herself." },
  { zh: "鑿麥積崖而葬之，號曰寂陵。", literal: "They carved out Maiji Cliff to bury her and called the tomb Silent Mound.", idiomatic: "They hollowed Maiji Cliff for her tomb and called it Silent Mound." },
  { zh: "夏，丞相泰召諸軍屯沙苑以備柔然。", literal: "In summer, Chancellor Tai summoned the armies to camp at Shayuan against Rouran.", idiomatic: "In summer, Yuwen Tai gathered the armies at Shayuan against Rouran." },
  { zh: "右僕射周惠達發士馬守京城，塹諸街巷，召雍州刺史王羆議之，羆不應召，謂使者曰：「若蠕蠕至渭北者，王羆自帥鄉里破之，不煩國家兵馬，何為天子城中作如此驚擾！", literal: "Right Vice Director Zhou Huida mobilized troops and horses to guard the capital, trenched the streets and lanes, and summoned Yongzhou inspector Wang Pi to counsel; Pi did not answer the summons and told the envoy, \"If the Rouran reach north of the Wei, Wang Pi himself will lead the countryside to break them—why trouble the state's troops and alarm the Son of Heaven's city like this!", idiomatic: "Zhou Huida, Right Vice Director, mobilized troops for the capital, trenched the streets, and summoned Wang Pi of Yongzhou; Pi would not come and told the envoy, \"If Rouran reach north of the Wei, Wang Pi will break them with his own district—why alarm the capital with state troops!" },
  { zh: "由周家小兒恇怯致此。", literal: "This comes of the Zhou family's cowardice.", idiomatic: "This is the Zhou household's cowardice." },
  { zh: "」柔然至夏州而退。", literal: "\" Rouran reached Xia province and withdrew.", idiomatic: "\" Rouran reached Xia province and withdrew." },
  { zh: "未幾，悼後遇疾殂。", literal: "Before long the Dowager Empress fell ill and died.", idiomatic: "Before long Dowager Empress Diao fell ill and died." },
  { zh: "五月，乙酉，魏行台宮延和、陝州刺史宮延慶降於東魏，東魏以河北馬場為義州以處之。", literal: "In the fifth month, on yiyou, Western Wei Mobile Headquarters Gong Yanhe and Shaan inspector Gong Yanqing surrendered to Eastern Wei; Eastern Wei made the Hebei horse pastures into Yi province to settle them.", idiomatic: "In the fifth month, on yiyou, Gong Yanhe of Western Wei's mobile headquarters and Gong Yanqing, inspector of Shaan, surrendered to Eastern Wei, which made the Hebei horse pastures into Yi province to house them." },
  { zh: "東魏陽州武公高永樂卒。", literal: "Eastern Wei's Duke of Yang province, Gao Yongle, died.", idiomatic: "Gao Yongle, Duke of Yang province in Eastern Wei, died." },
  { zh: "閏月，丁丑朔，日有食之。", literal: "In the intercalary month, on dingchou the first day of the month, there was a solar eclipse.", idiomatic: "In the intercalary month, on dingchou the new moon, there was an eclipse of the sun." },
  { zh: "己丑，東魏封皇兄景植為宜陽王，皇弟威為清河王，謙為穎川王。", literal: "On jichou, Eastern Wei enfeoffed the emperor's elder brother Jingzhi as Prince of Yiyang and younger brothers Wei as Prince of Qinghe and Qian as Prince of Yingchuan.", idiomatic: "On jichou, Eastern Wei made the emperor's elder brother Jingzhi Prince of Yiyang and younger brothers Wei Prince of Qinghe and Qian Prince of Yingchuan." },
  { zh: "六月，壬子，東魏華山王鷙卒。", literal: "In the sixth month, on renzi, Eastern Wei's Prince of Huashan, Zhi, died.", idiomatic: "In the sixth month, on renzi, Prince Zhi of Huashan in Eastern Wei died." },
  { zh: "秋，七月，丁亥，東魏使兼散騎常侍李象等來聘。", literal: "In autumn, the seventh month, on dinghai, Eastern Wei sent Associate Bearer of the Staff Li Xiang and others on a friendly mission.", idiomatic: "In autumn, the seventh month, on dinghai, Eastern Wei sent Li Xiang and others as envoys." },
  { zh: "八月，戊午，大赦。", literal: "In the eighth month, on wuwu, a general amnesty was proclaimed.", idiomatic: "In the eighth month, on wuwu, the Liang emperor proclaimed amnesty." },
  { zh: "九月，戊戌，司空袁昂卒，遺疏不受贈謚，敕諸子勿上行狀及立銘志。", literal: "In the ninth month, on wuxu, Minister of Works Yuan Ang died; in his final memorial he refused posthumous gifts and titles and charged his sons not to submit a funeral report or set up an inscription.", idiomatic: "In the ninth month, on wuxu, Minister of Works Yuan Ang died; his last memorial refused posthumous honors and forbade his sons to file a funeral report or raise a stele." },
  { zh: "上不許，贈本官，謚穆正公。", literal: "The emperor did not permit it and posthumously gave his former office with the posthumous title Pure and Upright Duke.", idiomatic: "The Liang emperor would not allow it and gave his former rank with the posthumous title Duke Pure and Upright." },
  { zh: "冬，十一月，魏太師念賢卒。", literal: "In winter, the eleventh month, Western Wei Grand Tutor Nian Xian died.", idiomatic: "In winter, the eleventh month, Nian Xian, Grand Tutor of Western Wei, died." },
  { zh: "吐谷渾自莫折念生之亂，不通於魏。", literal: "Tuyuhun, since Mohe Niansheng's rebellion, had had no dealings with Wei.", idiomatic: "Tuyuhun, since Mohe Niansheng's rebellion, had broken contact with Western Wei." },
  { zh: "伏連籌卒，子誇呂立，始稱可汗，居伏俟城。", literal: "Fulianchou died and his son Kualü succeeded, first taking the title khan and dwelling at Fuhou city.", idiomatic: "Fulianchou died; his son Kualü succeeded, first styled himself khan, and dwelt at Fuhou city." },
  { zh: "其地東西三千里，南北千餘里，官有王、公、僕射、尚書、郎中、將軍之號。", literal: "His lands stretched three thousand li east and west and more than a thousand north and south; offices bore the titles king, duke, steward, secretary, gentleman, and general.", idiomatic: "His realm ran three thousand li east to west and more than a thousand north to south, with offices titled king, duke, steward, secretary, gentleman, and general." },
  { zh: "是歲，始遣使假道柔然，聘於東魏。", literal: "That year he first sent envoys by way of Rouran on a friendly mission to Eastern Wei.", idiomatic: "That year he first sent envoys through Rouran to Eastern Wei." },
  { zh: "高祖武皇帝十四大同七年（", literal: "Great Ancestor Emperor Wu, year 7 of the Datong era (", idiomatic: "Emperor Wu of Liang, seventh year of Datong (" },
  { zh: "辛酉，公元五四一年）", literal: "xinyou, 541 CE)", idiomatic: "xinyou, AD 541)" },
  { zh: "春，正月，辛巳，上祀南郊，大赦。", literal: "In spring, the first month, on xinsi, the emperor sacrificed at the southern suburb and proclaimed a general amnesty.", idiomatic: "In spring, the first month, on xinsi, the Liang emperor sacrificed at the southern suburb and proclaimed amnesty." },
  { zh: "辛丑，祀明堂。", literal: "On xinchou he sacrificed at the Bright Hall.", idiomatic: "On xinchou he sacrificed at the Bright Hall." },
  { zh: "宕昌王梁企定為其下所殺，弟彌定立。", literal: "Tanchang king Liang Qiding was killed by his subordinates; his younger brother Midian succeeded.", idiomatic: "King Qiding of Tanchang was killed by his men; his brother Midian succeeded." },
  { zh: "二月，乙巳，以彌定為河、梁二州刺史、宕昌王。", literal: "In the second month, on yisi, Midian was made inspector of He and Liang provinces and king of Tanchang.", idiomatic: "In the second month, on yisi, Midian was made inspector of He and Liang and king of Tanchang." },
  { zh: "辛亥，上耕藉田。", literal: "On xinhai the emperor plowed the sacred field.", idiomatic: "On xinhai the Liang emperor plowed the sacred field." },
  { zh: "魏幽州刺史順陽王仲景坐事賜死。", literal: "Western Wei's Youzhou inspector, Prince of Shunyang, Zhongjing, was ordered to death for an offense.", idiomatic: "Zhongjing, Prince of Shunyang and inspector of Youzhou in Western Wei, was ordered to die for an offense." },
  { zh: "三月，魏夏州刺史劉平伏據上郡反，大都督於謹討擒之。", literal: "In the third month, Western Wei's Xiazhou inspector Liu Pingfu held Shang commandery in rebellion; Grand Commander Yu Jin captured him.", idiomatic: "In the third month, Liu Pingfu, inspector of Xia in Western Wei, rebelled at Shang commandery; Yu Jin captured him." },
  { zh: "夏，五月，遣兼散騎常侍明少遐等聘於東魏。", literal: "In summer, the fifth month, Associate Bearer of the Staff Ming Shaoxia and others were sent on a friendly mission to Eastern Wei.", idiomatic: "In summer, the fifth month, Ming Shaoxia and others were sent as envoys to Eastern Wei." },
  { zh: "秋，七月，己卯，東魏宜陽王景植卒。", literal: "In autumn, the seventh month, on jimao, Eastern Wei's Prince of Yiyang, Jingzhi, died.", idiomatic: "In autumn, the seventh month, on jimao, Prince Jingzhi of Yiyang in Eastern Wei died." },
  { zh: "魏以侍中宇文測為大都督、行汾州事。", literal: "Western Wei made Palace Attendant Yuwen Ce Grand Commander and acting inspector of Fen.", idiomatic: "Western Wei made Palace Attendant Yuwen Ce Grand Commander with acting charge of Fen." },
  { zh: "測，深之兄也，為政簡惠，得士民心。", literal: "Ce was Shen's elder brother; his government was simple and kind and won officers and people alike.", idiomatic: "Ce was Shen's elder brother; his rule was spare and kind and won officers and people alike." },
  { zh: "地接東魏，東魏人數來寇抄，測擒獲之，命解縛，引與相見，為設酒殽，待以客禮，並給糧餼，衛送出境。", literal: "His territory bordered Eastern Wei; Eastern Wei men often came to raid; Ce captured them, ordered their bonds undone, received them face to face, set out wine and meat, treated them as guests, and gave grain and fodder, escorting them beyond the border.", idiomatic: "His border touched Eastern Wei; raiders came often. Ce took them, had bonds cut, feasted them as guests, gave grain and fodder, and escorted them out." },
  { zh: "東魏人大慚，不復為寇，汾、晉之間遂通慶吊，時論稱之。", literal: "Eastern Wei men were deeply ashamed and raided no more; between Fen and Jin congratulations and condolences flowed freely, and men of the time praised him.", idiomatic: "The easterners were ashamed and raided no more; Fen and Jin exchanged congratulations and condolences, and the age praised him." },
  { zh: "或告測交通境外者，丞相泰怒曰：「測為我安邊，我知其志，何得間我骨肉！", literal: "Someone reported that Ce had dealings beyond the border; Chancellor Tai grew angry and said, \"Ce secures my frontier for me—I know his heart. How dare you come between my own flesh!", idiomatic: "Someone accused Ce of traffic beyond the border. Yuwen Tai raged: \"Ce holds my frontier—I know his heart. Who dares set kin against kin!" },
  { zh: "」命斬之。", literal: "\" He ordered the accuser beheaded.", idiomatic: "\" He had the accuser beheaded." },
  { zh: "魏丞相泰欲革易時政，為強國富民之法，大行台度支尚書兼司農卿蘇綽盡其智能，贊成其事，減官員，置二長，並置屯田以資軍國。", literal: "Western Wei Chancellor Tai wished to reform the government of the time and enact laws to strengthen the state and enrich the people; Grand Mobile Headquarters Director of Revenue and concurrent Minister of Agriculture Su Chuo gave all his wit to assist and complete the work—reducing officials, establishing two chiefs, and setting up garrison fields to supply army and state.", idiomatic: "Yuwen Tai wished to reform government and enrich the state; Su Chuo of the grand mobile headquarters gave all his wit—fewer officials, two chiefs, garrison fields for army and state." },
  { zh: "又為六條詔書，九月，始奏行之：一曰清心，二曰敦教化，三曰盡地利，四曰擢賢良，五曰恤獄訟，六曰均賦役。", literal: "He also drafted six articles of edict; in the ninth month they were first submitted and put into practice: first, purify the heart; second, thickly teach transformation; third, exhaust the land's advantage; fourth, promote the worthy; fifth, pity lawsuits; sixth, equalize levies and corvée.", idiomatic: "He also drafted six articles of edict; in the ninth month they took force: purify the heart; teach transformation; use the land; promote worthies; pity lawsuits; equalize levies and corvée." },
  { zh: "泰甚重之，嘗置諸坐右，又令百司習誦之，其牧守令長非通六條及計帳者，不得居官。", literal: "Tai greatly valued them, often kept them at his right hand, and ordered the hundred offices to study and recite them; prefects, defenders, magistrates, and chiefs who did not master the six articles and the accounts could not hold office.", idiomatic: "Tai prized them, kept them at hand, and made every office recite them; no magistrate who failed the six articles and the accounts could keep his post." },
  { zh: "東魏詔群官於麟趾閣議定法制，謂之《麟趾格》，冬，十月，甲寅，頒行之。", literal: "Eastern Wei ordered the officials to fix law at the Unicorn Toe Pavilion—called the Unicorn Toe Code; in winter, the tenth month, on jiayin, it was promulgated.", idiomatic: "Eastern Wei had officials fix law at the Unicorn Toe Pavilion—the Unicorn Toe Code; in winter, the tenth month, on jiayin, it was promulgated." },
  { zh: "乙巳，東魏發夫五萬築漳濱堰，三十五日罷。", literal: "On yisi Eastern Wei drafted fifty thousand laborers to build the Zhang embankment; in thirty-five days the work stopped.", idiomatic: "On yisi Eastern Wei drafted fifty thousand men for the Zhang embankment; in thirty-five days the work stopped." },
  { zh: "十一月，丙戌，東魏以彭城王韶為太尉，度支尚書胡僧敬為司空。", literal: "In the eleventh month, on bingxu, Eastern Wei made Prince Shao of Pengcheng Grand Commandant and Director of Revenue Hu Sengjing Minister of Works.", idiomatic: "In the eleventh month, on bingxu, Eastern Wei made Prince Shao of Pengcheng Grand Commandant and Hu Sengjing, Director of Revenue, Minister of Works." },
  { zh: "僧敬名虔，以字行，國珍之兄孫，東魏主之舅也。", literal: "Sengjing's given name was Qian; he went by his style; he was National Treasure's elder brother's grandson and the Eastern Wei sovereign's maternal uncle.", idiomatic: "Sengjing styled Qian and was National Treasure's grand-nephew and the Eastern Wei emperor's uncle on the mother's side." },
  { zh: "十二月，東魏遣兼散騎常侍李騫來聘。", literal: "In the twelfth month, Eastern Wei sent Associate Bearer of the Staff Li Qian on a friendly mission.", idiomatic: "In the twelfth month, Eastern Wei sent Li Qian as envoy." },
  { zh: "交趾李賁世為豪右，仕不得志。", literal: "Li Ben of Jiaozhi had been a great house for generations; he could not advance in office.", idiomatic: "Li Ben of Jiaozhi was a great house for generations but could not rise in office." },
  { zh: "有並韶者，富於詞藻，詣選求官，吏部尚書蔡撙以並姓無前賢，除廣陽門郎；", literal: "There was one Bing Shao, rich in letters; he sought office through selection; Minister of Personnel Cai Bo, because the Bing surname had no former worthies, made him Gentleman at the Guangyang Gate;", idiomatic: "Bing Shao, rich in letters, sought office; Cai Bo of Personnel, because the Bing had no former worthies, made him Gentleman at the Guangyang Gate;" },
  { zh: "韶恥之。", literal: "Shao was shamed.", idiomatic: "Shao was shamed." },
  { zh: "賁與韶還鄉里，謀作亂，會交州刺史武林侯咨以刻暴失眾心，時賁監德州，因連結數州豪傑俱反。", literal: "Ben and Shao returned to their native place and plotted rebellion; it happened that Jiaozhi inspector Marquis of Wulin, Zi, was harsh and had lost the people's hearts; Ben was then supervising Dezhou and so linked several provinces' great houses in joint revolt.", idiomatic: "Ben and Shao went home to rebel; Inspector Zi of Wulin was harsh and had lost the people; Ben, supervising Dezhou, linked magnates of several provinces in revolt." },
  { zh: "咨輸賄於賁，奔還廣州。", literal: "Zi paid bribes to Ben and fled back to Guangzhou.", idiomatic: "Zi bribed Ben and fled to Guangzhou." },
  { zh: "上遣咨與高州刺史孫冏、新州刺史盧子雄將兵擊之。", literal: "The emperor sent Zi with Gaozhou inspector Sun Tong and Xinzhou inspector Lu Zixiong to lead troops against him.", idiomatic: "The Liang emperor sent Zi with Sun Tong of Gaozhou and Lu Zixiong of Xinzhou against him." },
  { zh: "咨，恢之子也。", literal: "Zi was Hui's son.", idiomatic: "Zi was Hui's son." },
  { zh: "是歲，魏又益新制十二條。", literal: "That year Western Wei again added twelve new articles.", idiomatic: "That year Western Wei added twelve new articles." },
  { zh: "東魏丞相歡以諸州調絹不依舊式，民甚苦之，奏令悉以四十尺為匹。", literal: "Eastern Wei Chancellor Huan, because the provinces' silk levies did not follow the old measure, and the people suffered greatly, memorialized that all should use forty chi to the bolt.", idiomatic: "Gao Huan, because provincial silk levies ignored the old measure and the people suffered, ordered every bolt forty chi." },
  { zh: "魏自喪亂以來，農商失業，六鎮之民相帥內徙，就食齊、晉，歡因之以成霸業。", literal: "Since the disorders Wei's farmers and merchants had lost their trades; the people of the six garrisons had led one another inward to seek food in Qi and Jin, and Huan had thereby achieved hegemony.", idiomatic: "Since the disorders, farmers and merchants had failed; the six garrisons had moved inward to Qi and Jin for food, and Huan had built hegemony on them." },
  { zh: "東西分裂，連年戰爭，河南州郡鞠為茂草，公私困竭，民多餓死。", literal: "East and west were split and warred year after year; Henan's provinces and commanderies were trampled to weeds; public and private were exhausted and many starved.", idiomatic: "East and west split and warred year on year; Henan's commanderies were weeds; public and private were drained and many starved." },
  { zh: "歡命諸州濱河及津、梁皆置倉積穀以相轉漕，供軍旅，備饑饉，又於幽、瀛、滄、青四州傍海煮鹽。", literal: "Huan ordered all provinces along the river and at fords and bridges to set granaries and store grain for relay transport, to supply the army and guard against famine; he also had Yan, Ying, Cang, and Qing, the four provinces beside the sea, boil salt.", idiomatic: "Huan ordered river provinces and every ford and bridge to set granaries for relay grain for the army and famine; Yan, Ying, Cang, and Qing by the sea boiled salt." },
  { zh: "軍國之費，粗得周贍。", literal: "Army and state expenses were roughly provided for.", idiomatic: "Army and state expenses were roughly met." },
  { zh: "至是，東方連歲大稔，谷斛至九錢，山東之民稍復甦息矣。", literal: "By then the east had had great harvests several years running; grain was nine cash the hu, and the people of Shandong began to breathe again.", idiomatic: "By then the east had harvested several years; grain sold for nine cash the hu, and Shandong began to breathe again." },
  { zh: "東魏尚書令高澄尚靜帝妹馮翊長公主，生子孝琬，朝貴賀之，澄曰：「此至尊之甥，先賀至尊。", literal: "Eastern Wei Minister over the Masses Gao Cheng married the Quiet Emperor's younger sister, the Princess of Fengyi the Long; she bore son Xiaowan; the court nobles congratulated him, and Cheng said, \"This is His Majesty's sister's child—congratulate His Majesty first.", idiomatic: "Gao Cheng married the Quiet Emperor's sister, Princess of Fengyi the Long, and had Xiaowan; court nobles congratulated him. Cheng said, \"This is the emperor's sister's child—congratulate the emperor first." },
  { zh: "」三日，帝幸其第，賜錦彩布絹萬匹。", literal: "\" Three days later the emperor visited his house and gave ten thousand bolts of brocade, silk, and cloth.", idiomatic: "\" Three days later the emperor visited his house and gave ten thousand bolts of brocade, silk, and cloth." },
  { zh: "於是諸貴競致禮遺，貨滿十室。", literal: "Thereupon the nobles vied to send gifts until ten rooms were full of goods.", idiomatic: "Then the nobles vied in gifts until ten rooms were piled with goods." },
  { zh: "東魏臨淮王孝友表曰：「令制百家為族，二十五家為閭，五家為比。", literal: "Eastern Wei Prince of Linhuai, Xiaoyou, memorialized, saying, \"The present system makes a hundred households a clan, twenty-five a lane, and five a group.", idiomatic: "Prince Xiaoyou of Linhuai in Eastern Wei memorialized: \"The present system makes a hundred households a clan, twenty-five a lane, five a group." },
  { zh: "百家之內有帥二十五，征發皆免，苦樂不均，羊少狼多，復有蠶食，此之為弊久矣。", literal: "Within a hundred households there are twenty-five chiefs exempt from levies; joy and suffering are unequal—few sheep, many wolves, and again there is nibbling away; this harm has been long.", idiomatic: "Within a hundred households twenty-five chiefs are exempt from levies—joy and suffering unequal, few sheep and many wolves, and more nibbling away; the harm is old." },
  { zh: "京邑諸坊，或七八百家唯一里正、二史，庶事無闕，而況外州乎！", literal: "In the capital wards, seven or eight hundred households sometimes have only one lane chief and two clerks, yet nothing is lacking in affairs—how much more in outer provinces!", idiomatic: "In the capital, seven or eight hundred households sometimes have only one lane chief and two clerks, yet nothing lacks—how much more in outer provinces!" },
  { zh: "請依舊置三正之名不改，而每閭止為二比，計族省十二丁，貲絹、番兵，所益甚多。", literal: "I beg to keep the old name of three chiefs unchanged but make each lane only two groups, reckoning twelve men saved per clan—silk levies and frontier duty would gain greatly.", idiomatic: "Keep the three chiefs' names but make each lane only two groups—twelve men saved per clan, with great gain in silk and frontier duty.\"" },
  { zh: "」事下尚書，寢不行。", literal: "\" The matter went down to the Ministry of Works and slept without action.", idiomatic: "\" It went to the Ministry of Works and slept." },
  { zh: "安成望族劉敬躬以妖術惑眾，人多信之。", literal: "Liu Jinggong of the An Cheng great house bewitched the masses with sorcery; many believed him.", idiomatic: "Liu Jinggong of the An Cheng magnates bewitched the people with sorcery; many believed." },
  { zh: "高祖武皇帝十四大同八年（", literal: "Great Ancestor Emperor Wu, year 8 of the Datong era (", idiomatic: "Emperor Wu of Liang, eighth year of Datong (" },
  { zh: "壬戌，公元五四二年）", literal: "renxu, 542 CE)", idiomatic: "renxu, AD 542)" },
  { zh: "春，正月，敬躬據郡反，改元永漢，署官屬，進攻廬陵，逼豫章。", literal: "In spring, the first month, Jinggong held the commandery in rebellion, changed the era to Eternal Han, appointed officials, advanced on Luling, and pressed Yuzhang.", idiomatic: "In spring, the first month, Jinggong rebelled in the commandery, styled his era Eternal Han, appointed officials, marched on Luling, and pressed Yuzhang." },
  { zh: "南方久不習兵，人情擾駭，豫章內史張綰募兵以拒之。", literal: "The south had long been unused to war; hearts were alarmed; Yuzhang interior minister Zhang Wan raised troops to resist.", idiomatic: "The south had long been unused to war; hearts quaked; Zhang Wan, interior minister of Yuzhang, raised troops to resist." },
  { zh: "綰，纘之弟也。", literal: "Wan was Zuan's younger brother.", idiomatic: "Wan was Zuan's younger brother." },
  { zh: "二月，戊戌，江州刺史湘東王繹遣司馬王僧辯、中兵曹子郢討敬躬，受綰節度。", literal: "In the second month, on wuxu, Jiangzhou inspector Prince of Xiangdong, Yi, sent Mobile Headquarters Major Wang Sengbian and Central Troops Cao Ziyu to attack Jinggong, under Wan's command.", idiomatic: "In the second month, on wuxu, Prince Yi of Xiangdong, inspector of Jiangzhou, sent Wang Sengbian and Cao Ziyu against Jinggong under Wan's command." },
  { zh: "三月，戊辰，擒敬躬，送建康，斬之。", literal: "In the third month, on wuchen, Jinggong was captured, sent to Jiankang, and beheaded.", idiomatic: "In the third month, on wuchen, Jinggong was taken, sent to Jiankang, and beheaded." },
  { zh: "僧辯，神念之子也，該博辯捷，器宇肅然，雖射不穿札，而志氣高遠。", literal: "Sengbian was Shennian's son; he was broadly learned, quick in debate, and grave in bearing; though his archery did not pierce a leaf, his will was high and far.", idiomatic: "Sengbian was Shennian's son—learned, quick in debate, grave in bearing; though his arrow did not pierce a leaf, his will was high and far." },
  { zh: "魏初置六軍。", literal: "Western Wei first established six armies.", idiomatic: "Western Wei first established six armies." },
  { zh: "夏，四月，丙寅，東魏使兼散騎常侍李繪來聘。", literal: "In summer, the fourth month, on bingyin, Eastern Wei sent Associate Bearer of the Staff Li Hui on a friendly mission.", idiomatic: "In summer, the fourth month, on bingyin, Eastern Wei sent Li Hui as envoy." },
  { zh: "繪，元忠之從子也。", literal: "Hui was Yuanzhong's younger cousin's son.", idiomatic: "Hui was grandson of Yuanzhong's younger cousin." },
  { zh: "東魏丞相歡朝於鄴。", literal: "Eastern Wei Chancellor Huan attended court at Ye.", idiomatic: "Gao Huan attended court at Ye." },
  { zh: "司徒孫騰坐事免；", literal: "Minister of Works Sun Teng was dismissed for an offense;", idiomatic: "Sun Teng, Minister of Works, was dismissed for an offense;" },
  { zh: "乙酉，以彭城王韶錄尚書事，侍中廣陽王湛為太尉，尚書右僕射高隆之為司徒。", literal: "on yiyou Prince Shao of Pengcheng was made to record affairs of the Masters of Writing, Palace Attendant Prince Zhan of Guangyang Grand Commandant, and Right Vice Director of the Masters of Writing Gao Longzhi Minister of Works.", idiomatic: "on yiyou Prince Shao of Pengcheng recorded Masters of Writing affairs, Prince Zhan of Guangyang became Grand Commandant, and Gao Longzhi Right Vice Director became Minister of Works." },
  { zh: "初，太傅尉景與丞相歡同歸爾朱榮，其妻，歡之姊也，自恃勳戚，貪縱不法，為有司所劾，繫獄；", literal: "At first Grand Tutor Wei Jing had returned with Chancellor Huan to Erzhu Rong; his wife was Huan's elder sister; relying on merit and kinship she was greedy and lawless and was impeached by the authorities and imprisoned;", idiomatic: "At first Wei Jing had returned with Gao Huan to Erzhu Rong; Jing's wife was Huan's elder sister; trusting merit and kinship she was greedy and lawless and was impeached and imprisoned;" },
  { zh: "歡三詣闕泣請，乃得免死。", literal: "Huan thrice went to the palace weeping to beg, and only then was death spared.", idiomatic: "Huan thrice went to the palace weeping to beg, and only then was death spared." },
  { zh: "丁亥，降為驃騎大將軍、開府儀同三司。", literal: "On dinghai he was reduced to Rapid Cavalry General with the Grandee title Opening the Mansion and Equal in Honor to the Three Dukes.", idiomatic: "On dinghai he was reduced to Rapid Cavalry General with Opening the Mansion Equal to the Three Dukes." },
  { zh: "歡往造之，景臥不起，大叫曰：「殺我時趣邪！", literal: "Huan went to visit him; Jing lay and would not rise, crying loudly, \"When you killed me you were in a hurry, were you!", idiomatic: "Huan went to visit; Jing lay and would not rise, shouting, \"When you killed me you were in a hurry, were you!" },
  { zh: "」歡撫而拜謝之。", literal: "\" Huan stroked him and bowed in apology.", idiomatic: "\" Huan stroked him and bowed in apology." },
  { zh: "辛卯，以庫狄干為太傅，以領軍將軍婁昭為大司馬，封祖裔為尚書右僕射。", literal: "On xinmao Kudie Gan was made Grand Tutor, Army Supervisor Lou Zhao Grand Marshal, and Feng Zuyi Minister of Works.", idiomatic: "On xinmao Kudie Gan became Grand Tutor, Lou Zhao Army Supervisor became Grand Marshal, and Feng Zuyi became Minister of Works." },
  { zh: "六月，甲辰，歡還晉陽。", literal: "In the sixth month, on jiachen, Huan returned to Jinyang.", idiomatic: "In the sixth month, on jiachen, Gao Huan returned to Jinyang." },
  { zh: "八月，庚戌，東魏以開府儀同三司、吏部尚書侯景為兼尚書僕射、河南道大行台，隨機防討。", literal: "In the eighth month, on gengxu, Eastern Wei made Bearer of the Staff Equal to the Three Dukes and Minister of Personnel Hou Jing concurrent Minister of Works and Grand Mobile Headquarters of Henan Route, to defend and strike as occasion required.", idiomatic: "In the eighth month, on gengxu, Eastern Wei made Hou Jing concurrent Minister of Works and Grand Mobile Headquarters of Henan Route, to defend and strike as occasion required." },
  { zh: "魏以王盟為太保。", literal: "Western Wei made Wang Meng Grand Protector.", idiomatic: "Western Wei made Wang Meng Grand Protector." },
  { zh: "東魏丞相歡擊魏，入自汾、絳，連營四十里，丞相泰使王思政守玉壁以斷其道。", literal: "Eastern Wei Chancellor Huan attacked Wei, entering from Fen and Jiang, encamping in a line forty li long; Chancellor Tai sent Wang Sizheng to hold Yubi and cut his road.", idiomatic: "Gao Huan attacked Western Wei from Fen and Jiang, encamping forty li deep; Yuwen Tai sent Wang Sizheng to hold Yubi and block his road." },
  { zh: "歡以書招思政曰：「若降，當授以并州。", literal: "Huan wrote to summon Sizheng, saying, \"If you surrender, I will give you Bing province.", idiomatic: "Huan wrote Sizheng: \"Surrender and I give you Bing.\"" },
  { zh: "」思政復書曰：「可朱渾道元降，何以不得？", literal: "\" Sizheng replied, \"Kezhun Hun Daoyuan surrendered—why did he not receive it?", idiomatic: "\" Sizheng replied, \"Kezhun Hun Daoyuan surrendered—why was he denied?" },
  { zh: "」冬，十月，己亥，歡圍玉壁，凡九日，遇大雪，士卒饑凍，多死者，遂解圍去。", literal: "\" In winter, the tenth month, on jihai, Huan besieged Yubi nine days; heavy snow fell, soldiers hungered and froze, and many died; he then raised the siege and left.", idiomatic: "\" In winter, the tenth month, on jihai, Huan besieged Yubi nine days; snow fell, men starved and froze, and many died; he raised the siege and left." },
  { zh: "魏遣太子欽鎮蒲板。", literal: "Western Wei sent the crown prince, Qin, to garrison Puban.", idiomatic: "Western Wei sent Crown Prince Qin to garrison Puban." },
  { zh: "丞相泰出軍蒲板，至皁莢，聞歡退渡汾，追之不及。", literal: "Chancellor Tai led troops out from Puban to Zaojia; hearing Huan had crossed the Fen in retreat, he pursued but could not overtake.", idiomatic: "Yuwen Tai marched from Puban to Zaojia; hearing Huan had recrossed the Fen in retreat, he pursued but could not catch him." },
  { zh: "十一月，東魏以可朱渾道元為并州刺史。", literal: "In the eleventh month, Eastern Wei made Kezhun Hun Daoyuan inspector of Bing.", idiomatic: "In the eleventh month, Eastern Wei made Kezhun Hun Daoyuan inspector of Bing." },
  { zh: "十二月，魏主狩於華陰，大享將士，丞相泰帥諸將朝之。", literal: "In the twelfth month, the Wei sovereign hunted at Huayin, feasted the officers and soldiers greatly, and Chancellor Tai led the generals to attend him.", idiomatic: "In the twelfth month, the Western Wei emperor hunted at Huayin and feasted the army; Yuwen Tai led the generals to attend." },
  { zh: "起萬壽殿於沙苑北。", literal: "He raised Long Life Hall north of Shayuan.", idiomatic: "He raised Long Life Hall north of Shayuan." },
  { zh: "辛亥，東魏遣兼散騎常侍楊斐來聘。", literal: "On xinhai Eastern Wei sent Associate Bearer of the Staff Yang Fei on a friendly mission.", idiomatic: "On xinhai Eastern Wei sent Yang Fei as envoy." },
  { zh: "孫冏、盧子雄討李賁，以春瘴方起，請待至秋；", literal: "Sun Tong and Lu Zixiong attacked Li Ben; because spring miasma was rising they asked to wait until autumn;", idiomatic: "Sun Tong and Lu Zixiong attacked Li Ben; spring miasma was rising and they asked to wait until autumn;" },
  { zh: "廣州刺史新渝侯映不許，武林侯咨又趣之。", literal: "Guangzhou inspector Marquis of Xinyu, Ying, would not permit it, and Marquis of Wulin, Zi, pressed them on.", idiomatic: "Inspector Ying of Xinyu would not allow it, and Zi of Wulin pressed them on." },
  { zh: "冏等至合浦，死者什六七，眾潰而歸。", literal: "Tong and the rest reached Hepu; six or seven in ten died; the host broke and returned.", idiomatic: "They reached Hepu; six or seven in ten died; the host broke and fled home." },
  { zh: "映，憺之子也。", literal: "Ying was Dan's son.", idiomatic: "Ying was Dan's son." },
  { zh: "武林侯咨奏冏及子雄與賊交通，逗留不進，敕於廣州賜死。", literal: "Zi of Wulin memorialized that Tong and Zixiong had dealings with the bandits and lingered without advancing; an edict ordered them executed at Guangzhou.", idiomatic: "Zi memorialized that Tong and Zixiong trafficked with the rebels and lingered; an edict ordered them executed at Guangzhou." },
  { zh: "子雄弟子略、子烈、主帥廣陵杜天合及弟僧明、新安周文育等帥子雄之眾攻廣州，欲殺映、咨，為子雄復冤。", literal: "Zixiong's younger brother's son Lue, son Lie, commander of Guangling Du Tianhe and younger brother Sengming, and Xin'an Zhou Wenyü led Zixiong's troops against Guangzhou, intending to kill Ying and Zi and avenge Zixiong.", idiomatic: "Lue and Lie, Zixiong's kin, with Du Tianhe of Guangling, his brother Sengming, and Zhou Wenyü of Xin'an led Zixiong's troops on Guangzhou to kill Ying and Zi and avenge him." },
  { zh: "西江督護、高要太守吳興陳霸先帥精甲三千救之，大破子略等，殺天合，擒僧明、文育。", literal: "West River Protector and Gaoyao prefect Chen Baxian of Wuxing led three thousand picked armor to the rescue, routed Lue and the rest, killed Tianhe, and captured Sengming and Wenyü.", idiomatic: "Chen Baxian of Wuxing, West River Protector and Gaoyao prefect, led three thousand picked men to the rescue, routed them, killed Tianhe, and took Sengming and Wenyü." },
  { zh: "霸先以僧明、文育驍勇過人，釋之，以為主帥。", literal: "Baxian, because Sengming and Wenyü were surpassingly brave, released them and made them his commanders.", idiomatic: "Baxian, finding Sengming and Wenyü surpassingly brave, released them and made them his commanders." },
  { zh: "詔以霸先為直閣將軍。", literal: "An edict made Baxian Direct Attendant.", idiomatic: "An edict made Baxian Direct Attendant." },
  { zh: "魏丞相泰妻馮翊公主生子覺。", literal: "Western Wei Chancellor Tai's wife, the Princess of Fengyi, bore son Jue.", idiomatic: "Yuwen Tai's wife, the Princess of Fengyi, bore Jue." },
  { zh: "東魏以光州刺史李元忠為侍中。", literal: "Eastern Wei made Guangzhou inspector Li Yuanzhong Palace Attendant.", idiomatic: "Eastern Wei made Li Yuanzhong of Guangzhou Palace Attendant." },
  { zh: "元忠雖處要任，不以物務干懷，唯飲酒自娛。", literal: "Though Yuanzhong held a weighty post, worldly affairs did not touch his mind; he drank for pleasure alone.", idiomatic: "Though Yuanzhong held a weighty post, worldly affairs did not touch him; he drank for pleasure alone." },
  { zh: "丞相歡欲用為僕射，世子澄言其放達常醉，不可委以台閣。", literal: "Chancellor Huan wished to use him as Minister of Works; the heir Cheng said he was free and always drunk and could not be entrusted with the secretariat.", idiomatic: "Gao Huan wished to make him Minister of Works; heir Cheng said he was free and always drunk and unfit for the secretariat." },
  { zh: "其子搔聞之，請節酒，元忠曰：「我言作僕射不勝飲酒樂，爾愛僕射，宜勿飲酒。", literal: "His son Sao heard of it and asked him to drink less; Yuanzhong said, \"I say being Minister of Works is not as good as the joy of drinking—if you love the post of Minister of Works, you ought not to drink.", idiomatic: "His son Sao asked him to drink less; Yuanzhong said, \"Being Minister of Works is not the joy of drinking—if you love that post, you ought not drink.\"" },
  { zh: "高祖武皇帝十四大同九年（", literal: "Great Ancestor Emperor Wu, year 9 of the Datong era (", idiomatic: "Emperor Wu of Liang, ninth year of Datong (" },
  { zh: "癸亥，公元五四三年）", literal: "guihai, 543 CE)", idiomatic: "guihai, AD 543)" },
  { zh: "春，正月，壬戌，東魏大赦，改元武定。", literal: "In spring, the first month, on renxu, Eastern Wei proclaimed a general amnesty and changed the era to Martial Settlement.", idiomatic: "In spring, the first month, on renxu, Eastern Wei proclaimed amnesty and changed the era to Martial Settlement." },
  { zh: "東魏御史中尉高仲密取吏部郎崔暹之妹，既而棄之，由是與暹有隙。", literal: "Eastern Wei Imperial Censor Gao Zhongmi took the younger sister of Personnel Gentleman Cui Xuan, then cast her aside, and from this had a rift with Xuan.", idiomatic: "Gao Zhongmi, Eastern Wei Imperial Censor, married Cui Xuan of Personnel's sister, then cast her aside, and quarreled with Xuan." },
  { zh: "仲密選用御史，多其親戚鄉黨，高澄奏令改選；", literal: "Zhongmi in selecting censors favored many of his kin and townsmen; Gao Cheng memorialized that the selection be changed;", idiomatic: "Zhongmi favored kin and townsmen in selecting censors; Gao Cheng had the list changed;" },
  { zh: "暹方為澄所寵任，仲密疑其構己，愈恨之。", literal: "Xuan was then Cheng's favorite; Zhongmi suspected he had framed him and hated him the more.", idiomatic: "Xuan was Cheng's favorite; Zhongmi suspected a frame and hated him more." },
  { zh: "仲密後妻李氏艷而慧，澄見而悅之，李氏不從，衣服皆裂，以告仲密，仲密益怨。", literal: "Zhongmi's later wife, the Li, was beautiful and clever; Cheng saw her and desired her; the Li would not yield and her clothes were all torn; she told Zhongmi and his hatred grew.", idiomatic: "Zhongmi's later wife Li was beautiful and clever; Cheng desired her; Li refused and her clothes were torn; she told Zhongmi and his hatred grew." },
  { zh: "尋出為北豫州刺史，陰謀外叛。", literal: "Before long he was sent out as inspector of North Yuzhou and secretly plotted to rebel abroad.", idiomatic: "Soon he went out as inspector of North Yuzhou and secretly plotted defection." },
  { zh: "丞相歡疑之，遣鎮城奚壽興典軍事，仲密但知民務。", literal: "Chancellor Huan suspected him and sent Xi Shouxing of the garrison city to handle military affairs; Zhongmi knew only civil affairs.", idiomatic: "Gao Huan suspected him and sent Xi Shouxing to handle military affairs; Zhongmi handled only civil affairs." },
  { zh: "仲密置酒延壽興，伏壯士，執之，二月，壬申，以虎牢叛，降魏。", literal: "Zhongmi set wine for Shouxing, hid strong men, and seized him; in the second month, on renshen, he rebelled at Tiger Mound and surrendered to Wei.", idiomatic: "Zhongmi feasted Shouxing, hid strong men, and seized him; in the second month, on renshen, he rebelled at Tiger Mound and surrendered to Western Wei." },
  { zh: "魏以仲密為侍中、司徒。", literal: "Western Wei made Zhongmi Palace Attendant and Minister of Works.", idiomatic: "Western Wei made Zhongmi Palace Attendant and Minister of Works." },
  { zh: "歡以仲密之叛由崔暹，將殺之，高澄匿暹，為之固請，歡曰：「我丐其命，須與苦手。", literal: "Huan, because Zhongmi's rebellion came from Cui Xuan, was about to kill Xuan; Gao Cheng hid Xuan and pleaded hard for him; Huan said, \"I spare his life, but he must have a taste of the staff.", idiomatic: "Huan blamed Cui Xuan for the revolt and was about to kill him; Gao Cheng hid Xuan and pleaded; Huan said, \"I spare his life, but he must taste the staff." },
  { zh: "」澄乃出暹，而謂大行台都官郎陳元康曰：「卿使崔暹得杖，勿復相見。", literal: "\" Cheng then produced Xuan and told Grand Mobile Headquarters Director of Justice Chen Yuankang, \"If you let Cui Xuan take the staff, see me no more.", idiomatic: "\" Cheng produced Xuan and told Chen Yuankang of Justice, \"If Xuan takes the staff, see me no more." },
  { zh: "」元康為之言於歡曰：「大王方以天下付大將軍，大將軍有一崔暹不能免其杖，父子尚爾，況於它人！", literal: "\" Yuankang spoke to Huan for him, saying, \"Your Highness is about to entrust the realm to the Grand General; the Grand General has one Cui Xuan and cannot spare him the staff—if father and son are thus, what of others!", idiomatic: "\" Yuankang told Huan, \"You entrust the realm to the Grand General; he has one Cui Xuan and cannot spare him the staff—if father and son are thus, what of others!" },
  { zh: "」歡乃釋之。", literal: "\" Huan then released him.", idiomatic: "\" Huan released him." },
  { zh: "高季式在永安戍，仲密遣信報之；", literal: "Gao Jishi was garrisoning Yong'an; Zhongmi sent word to him;", idiomatic: "Gao Jishi garrisoned Yong'an; Zhongmi sent word;" },
  { zh: "季式走告歡，歡待之如舊。", literal: "Jishi ran to tell Huan, and Huan treated him as before.", idiomatic: "Jishi ran to tell Huan, and Huan treated him as before." },
  { zh: "魏丞相泰帥諸軍以應仲密，以太子少傅李遠為前驅，至洛陽，遣開府儀同三司於謹攻柏谷，拔之；", literal: "Western Wei Chancellor Tai led the armies to answer Zhongmi, with Crown Prince Tutor Li Yuan as vanguard; reaching Luoyang, he sent Bearer of the Staff Equal to the Three Dukes Yu Jin to attack Cypress Valley and took it;", idiomatic: "Yuwen Tai led the armies to answer Zhongmi with Li Yuan as vanguard; at Luoyang he sent Yu Jin to storm Cypress Valley and take it;" },
  { zh: "三月，壬申，圍河橋南城。", literal: "in the third month, on renshen, he besieged the south city at River Bridge.", idiomatic: "in the third month, on renshen, he besieged the south city at River Bridge." },
  { zh: "東魏丞相歡將兵十萬至河北，泰退軍瀍上，縱火船於上流以燒河橋。", literal: "Eastern Wei Chancellor Huan led a hundred thousand men to the north of the river; Tai withdrew the army to the Yi bank and set fire ships upstream to burn the river bridge.", idiomatic: "Gao Huan led a hundred thousand to the north bank; Tai withdrew to the Yi and sent fire ships upstream to burn the bridge." },
  { zh: "斛律金使行台郎中張亮以小艇百餘載長鎖，伺火船將至，以釘釘之，引鎖向岸，橋遂獲全。", literal: "Hulü Jin had Mobile Headquarters Gentleman Zhang Liang take more than a hundred small boats loaded with long chains; when the fire ships were about to arrive he nailed them, drew the chains to shore, and the bridge was saved whole.", idiomatic: "Hulü Jin had Zhang Liang take a hundred small boats with long chains; when the fire ships came he nailed them, drew the chains ashore, and the bridge stood." },
  { zh: "歡渡河，據邙山為陳，不進者數日。", literal: "Huan crossed the river, took Mount Mang for his battle line, and did not advance for several days.", idiomatic: "Huan crossed, formed line on Mount Mang, and did not advance for days." },
  { zh: "泰留輜重於瀍曲，夜，登邙山以襲歡。", literal: "Tai left baggage at the Yi bend; at night he climbed Mount Mang to strike Huan.", idiomatic: "Tai left baggage at the Yi bend; at night he climbed Mount Mang to strike Huan." },
  { zh: "候騎白歡曰：「賊距此四十餘里，蓐食乾飲而來。", literal: "Scouts told Huan, \"Bandits are forty-odd li from here, eating dry rations on the march.", idiomatic: "Scouts told Huan, \"The enemy is forty li off, eating dry on the march." },
  { zh: "」歡曰：「自當渴死！", literal: "\" Huan said, \"They will die of thirst themselves!", idiomatic: "\" Huan said, \"They will die of thirst themselves!" },
  { zh: "」乃正陣以待之。", literal: "\" He then set his ranks to wait.", idiomatic: "\" He set ranks and waited." },
  { zh: "戊申，黎明，泰軍與歡軍遇。", literal: "On wushen, at dawn, Tai's army and Huan's army met.", idiomatic: "On wushen, at dawn, Tai's army met Huan's." },
  { zh: "東魏彭樂以數千騎為右甄，沖魏軍之北垂，所向奔潰，遂馳入魏營。", literal: "Eastern Wei's Peng Yue led several thousand horse as the right wing, struck the northern flank of Wei's army, routed all before him, and galloped into the Wei camp.", idiomatic: "Peng Yue of Eastern Wei led several thousand horse on the right, shattered the northern flank, and galloped into the Wei camp." },
  { zh: "人告彭樂叛，歡甚怒。", literal: "Men reported Peng Yue had rebelled; Huan was very angry.", idiomatic: "Men reported Peng Yue had turned; Huan raged." },
  { zh: "俄而西北塵起，樂使來告捷，虜魏侍中、開府儀同三司、大都督臨洮王柬、蜀郡王榮宗、江夏王升、巨鹿王闡、譙郡王亮、詹事趙善及督將僚佐四十八人。", literal: "Soon dust rose in the northwest; Yue's messenger came to report victory, having captured Wei Palace Attendant, Bearer of the Staff Equal to the Three Dukes, Grand Commander Prince of Lintao, Dong, Prince of Shujun, Rongzong, Prince of Jiangxia, Sheng, Prince of Julu, Chan, Prince of Qiao, Liang, Grand Tutor Zhao Shan, and forty-eight officers and staff.", idiomatic: "Soon dust rose northwest; Yue's messenger reported victory—Palace Attendant Prince Dong of Lintao, Prince Rongzong of Shujun, Prince Sheng of Jiangxia, Prince Chan of Julu, Prince Liang of Qiao, Grand Tutor Zhao Shan, and forty-eight officers taken." },
  { zh: "諸將乘勝擊魏，大破之，斬首三萬餘級。", literal: "The generals pressed the victory and struck Wei, routing them utterly and taking more than thirty thousand heads.", idiomatic: "The generals pressed on and shattered Wei, taking more than thirty thousand heads." },
  { zh: "歡使彭樂追泰，泰窘，謂樂曰：「汝非彭樂邪？", literal: "Huan sent Peng Yue to pursue Tai; Tai was hard pressed and said to Yue, \"Are you not Peng Yue?", idiomatic: "Huan sent Peng Yue after Tai; Tai was cornered and said, \"Are you not Peng Yue?" },
  { zh: "癡男子！", literal: "Fool of a man!", idiomatic: "Fool of a man!" },
  { zh: "今日無我，明日豈有汝邪！", literal: "Today without me, tomorrow will there be you?", idiomatic: "Today without me, tomorrow will there be you?" },
  { zh: "何不急還營，收汝金寶！", literal: "Why not hurry back to camp and gather your gold and gems!", idiomatic: "Why not hurry back and gather your gold and gems!" },
  { zh: "」樂從其言，獲泰金帶一囊以歸，言於歡曰：「黑獺漏刃，破膽矣！", literal: "\" Yue followed his words, took a pouch of Tai's gold belt, and returned, telling Huan, \"The Black Badger slipped the blade—his courage is broken!", idiomatic: "\" Yue obeyed, took Tai's gold belt, and told Huan, \"The Black Badger slipped the blade—his courage is broken!" },
  { zh: "」歡雖喜其勝而怒其失泰，令伏諸地，親捽其頭，連頓之，並數以沙苑之敗，舉刃將下者三，噤齘良久。", literal: "\" Huan was glad of the victory but angry he had lost Tai; he had Yue lie on the ground, seized his head himself, and knocked it again and again, also reckoning up the defeat at Shayuan; thrice he raised the blade to strike and held his teeth a long while.", idiomatic: "\" Huan was glad of victory but furious Tai escaped; he had Yue lie down, seized his head and knocked it again and again, reckoning Shayuan; thrice he raised the blade and gnashed long." },
  { zh: "樂曰：「乞五千騎，復為王取之。", literal: "Yue said, \"I beg five thousand horse to take him again for my lord.", idiomatic: "Yue said, \"Give me five thousand horse and I will take him again.\"" },
  { zh: "」歡曰：「汝縱之何意？", literal: "\" Huan said, \"Why did you let him go?", idiomatic: "\" Huan said, \"Why did you let him go?" },
  { zh: "而言復取邪！", literal: "And speak of taking him again!", idiomatic: "And speak of taking him again!" },
  { zh: "」命取絹三千匹壓樂背，因以賜之。", literal: "\" He ordered three thousand bolts of silk piled on Yue's back and then gave them to him.", idiomatic: "\" He ordered three thousand bolts of silk piled on Yue's back, then gave them to him." },
  { zh: "明日，復戰，泰為中軍，中山公趙貴為左軍，領軍若干惠等為右軍。", literal: "The next day they fought again; Tai was center army, Duke of Zhongshan Zhao Gui left army, and Army Supervisor Ruogan Hui and others right army.", idiomatic: "Next day they fought again; Tai held center, Zhao Gui of Zhongshan the left, Ruogan Hui and others the right." },
  { zh: "中軍、右軍合擊東魏，大破之，悉俘其步卒。", literal: "Center and right together struck Eastern Wei, routed them utterly, and took all their foot soldiers prisoner.", idiomatic: "Center and right together shattered Eastern Wei and took every foot soldier." },
  { zh: "歡失馬，赫連陽順下馬以授歡。", literal: "Huan lost his horse; Helian Yangshun dismounted and gave his horse to Huan.", idiomatic: "Huan lost his horse; Helian Yangshun dismounted and gave him his." },
  { zh: "歡上馬走，從者步騎七人，追兵至，親信都督尉興慶曰：「王速去，興慶腰有百箭，足殺百人。", literal: "Huan mounted and fled; seven foot and horse followed; pursuers came up; trusted commander Wei Xingqing said, \"My lord, go quickly—Xingqing has a hundred arrows at his belt, enough to kill a hundred men.", idiomatic: "Huan mounted and fled with seven men; pursuers closed; Wei Xingqing said, \"My lord, go—I have a hundred arrows, enough for a hundred men." },
  { zh: "」歡曰：「事濟，以爾為懷州刺史；", literal: "\" Huan said, \"If the affair succeeds, I make you inspector of Hua;", idiomatic: "\" Huan said, \"If we win, you are inspector of Hua;" },
  { zh: "若死，用爾子！", literal: "if I die, I use your son!", idiomatic: "if I die, I use your son!" },
  { zh: "」興慶曰：「兒小，願用兄！", literal: "\" Xingqing said, \"My son is small—I wish to use my elder brother!", idiomatic: "\" Xingqing said, \"My son is small—use my brother!" },
  { zh: "」歡許之。", literal: "\" Huan consented.", idiomatic: "\" Huan consented." },
  { zh: "興慶拒戰，矢盡而死。", literal: "Xingqing held them off until his arrows were spent and he died.", idiomatic: "Xingqing held them until his arrows were spent and died." },
  { zh: "東魏軍士有逃奔魏者，告以歡所在，泰募勇敢三千人，皆執短兵，配大都督賀拔勝以攻之。", literal: "Eastern Wei soldiers who fled to Wei reported where Huan was; Tai recruited three thousand brave men, all with short weapons, and gave them to Grand Commander Heba Sheng to attack.", idiomatic: "Eastern Wei deserters told where Huan was; Tai took three thousand brave men with short weapons under Heba Sheng." },
  { zh: "勝識歡於行間，執槊與十三騎逐之，馳數里，槊刃垂及，因字之曰：「賀六渾，賀拔破胡必殺汝！", literal: "Sheng knew Huan in the ranks, took his spear with thirteen riders and chased him several li; the spear point nearly reached him, and he called by his style, \"He Liu Hun, Heba Pohu will surely kill you!", idiomatic: "Sheng knew Huan in the ranks, took his spear with thirteen riders and chased him; the point nearly reached him; he called, \"He Liu Hun, Heba Pohu will kill you!" },
  { zh: "」歡氣殆絕，河州刺史劉洪徽從傍射勝，中其二騎，武衛將軍段韶射勝馬，斃之。", literal: "\" Huan nearly lost breath; Hezhou inspector Liu Honghui shot from the side and hit two of his riders; Palace Guard General Duan Shao shot Sheng's horse and killed it.", idiomatic: "\" Huan nearly fainted; Liu Honghui of Hezhou shot from the side and dropped two riders; Duan Shao of the Palace Guard shot Sheng's horse dead." },
  { zh: "比副馬至，歡已逸去。", literal: "By the time the spare horse came, Huan had already escaped.", idiomatic: "Before the spare horse came, Huan was gone." },
  { zh: "勝歎曰：「今日不執弓矢，天也！", literal: "Sheng sighed, \"Today I did not carry bow and arrows—Heaven!", idiomatic: "Sheng sighed, \"Today I carried no bow—Heaven!" },
  { zh: "魏南郢州刺史耿令貴，大呼，獨入敵中，鋒刃亂下，人皆謂已死，俄奮刀而還。", literal: "Western Wei's Nanying inspector Geng Linggui shouted and entered the enemy alone; blades fell on every side and all thought him dead, but presently he flourished his sword and came back.", idiomatic: "Geng Linggui, inspector of Nanying in Western Wei, shouted and entered the enemy alone; blades fell everywhere and all thought him dead; then he flourished his sword and came back." },
  { zh: "如是數四，當令貴前者死傷相繼。", literal: "He did this four times; those before Linggui died and were wounded in succession.", idiomatic: "He did this four times; those before him fell in heaps." },
  { zh: "乃謂左右曰：「吾豈樂殺人！", literal: "He then told those at his side, \"Do I delight in killing!", idiomatic: "He told his men, \"Do I delight in killing!" },
  { zh: "壯士除賊，不得不爾。", literal: "A stalwart rids the realm of bandits—he cannot do otherwise.", idiomatic: "A stalwart rids bandits—he cannot do otherwise." },
  { zh: "若不能殺賊，又不為賊所傷，何異逐坐人也！", literal: "If he cannot kill bandits and is not wounded by bandits, how is he different from one who chases a seat!", idiomatic: "If he neither kills bandits nor is wounded by them, how is he different from one chasing a seat!" },
  { zh: "左軍趙貴等五將戰不利，東魏兵復振。", literal: "Left army Zhao Gui and five other generals fought ill; Eastern Wei troops rallied again.", idiomatic: "Zhao Gui and five generals on the left fought ill; Eastern Wei rallied." },
  { zh: "泰與戰，又不利。", literal: "Tai fought again and again without success.", idiomatic: "Tai fought again without success." },
  { zh: "會日暮，魏兵遂遁，東魏兵追之；", literal: "It happened to be evening; Wei troops then fled and Eastern Wei pursued;", idiomatic: "Evening came; Wei fled and Eastern Wei pursued." },
  { zh: "獨孤信、於謹收散卒自後擊之，追兵驚擾，魏諸軍由是得全。", literal: "Dugu Xin and Yu Jin gathered scattered soldiers and struck from behind; the pursuers were alarmed and thrown into confusion, and by this all Wei armies were saved whole.", idiomatic: "Dugu Xin and Yu Jin gathered the scattered and struck from behind; pursuers panicked, and every Wei army got clear." },
  { zh: "若於惠夜引去，東魏兵追之；", literal: "Ruogan Hui led away by night; Eastern Wei pursued;", idiomatic: "Ruogan Hui marched off by night; Eastern Wei pursued." },
  { zh: "惠徐下馬，顧命廚人營食，食畢，謂左右曰：「長安死，此中死，有以異乎？", literal: "Hui slowly dismounted, ordered the cook to prepare food, and when the meal was done told those at his side, \"To die in Chang'an or to die here—how are they different?", idiomatic: "Hui slowly dismounted, had the cook prepare food, and when it was done said, \"Die in Chang'an or die here—what difference?" },
  { zh: "」乃建旗鳴角，收散卒徐還；", literal: "\" He then raised banners and sounded horns, gathered scattered soldiers, and returned at leisure;", idiomatic: "\" He raised banners, sounded horns, gathered the scattered, and returned at leisure;" },
  { zh: "追騎疑有伏兵，不敢逼。", literal: "The pursuers suspected an ambush and did not dare press close.", idiomatic: "The pursuers suspected an ambush and did not dare press close." },
  { zh: "泰遂入關，屯渭上。", literal: "Tai then entered the pass and encamped on the Wei north bank.", idiomatic: "Yuwen Tai then entered the pass and encamped on the north bank of the Wei." },
  { zh: "歡進至陝，泰使開府儀同三司達奚武等拒之。", literal: "Huan advanced to Shaan; Tai sent Kaifu Yitong Sansi Daxi Wu and others to resist him.", idiomatic: "Gao Huan advanced to Shaan; Yuwen Tai sent Daxi Wu and others to block him." },
  { zh: "行台郎中封子繪言於歡曰：「混壹東西，正在今日。", literal: "Mobile Headquarters Director Feng Zihui said to Huan, \"To unify east and west—today is the day.", idiomatic: "Feng Zihui of the mobile headquarters said to Huan, \"To unify east and west—the moment is today." },
  { zh: "昔魏太祖平漢中，不乘勝取巴、蜀，失在遲疑，後悔無及。", literal: "In old times Emperor Taizu of Wei pacified Hanzhong but did not press the victory to take Ba and Shu; the loss lay in hesitation, and regret came too late.", idiomatic: "Long ago Emperor Taizu of Wei took Hanzhong but did not follow up to seize Ba and Shu; hesitation cost him, and he regretted it ever after." },
  { zh: "願大王不以為疑。", literal: "I beg Your Highness not to regard it with suspicion.", idiomatic: "I beg you, my lord, not to doubt it." },
  { zh: "」歡深然之，集諸將議進止，鹹以為「野無青草，人馬疲瘦，不可遠追。", literal: "\" Huan deeply agreed, gathered his generals to discuss advancing or halting, and all held that with no fresh grass in the fields and men and horses worn thin, they could not pursue far.", idiomatic: "Huan was deeply persuaded, called his generals to debate whether to advance, and all said, \"There is no fresh grass in the fields; men and horses are exhausted—they cannot be chased far.\"" },
  { zh: "」陳元康曰：「兩雄交爭，歲月已久。", literal: "\" Chen Yuankang said, \"Two great rivals have contended for years.", idiomatic: "Chen Yuankang said, \"Two great rivals have contended for years." },
  { zh: "今幸而大捷，天授我也，時不可失，當乘勝追之。", literal: "Now, by good fortune, we have won a great victory—Heaven has granted it to us; the moment must not be lost; we should press the victory while pursuit is still possible.", idiomatic: "Now, by good fortune, we have won a great victory—Heaven has granted it to us. The moment must not be lost; we should press the victory while pursuit is still possible.\"" },
  { zh: "」歡曰：「若遇伏兵，孤何以濟？", literal: "\" Huan said, \"If we meet an ambush, how shall I escape?", idiomatic: "Huan said, \"If we meet an ambush, how shall I escape?\"" },
  { zh: "」元康曰：「王前沙苑失利，彼尚無伏；", literal: "\" Yuankang said, \"When Your Highness lost at Shaxi, they still set no ambush;", idiomatic: "Yuankang said, \"When Your Highness lost at Shaxi, they still set no ambush;" },
  { zh: "今奔敗若此，何能遠謀！", literal: "now they flee in defeat like this—how could they plan far ahead!", idiomatic: "now they flee in defeat like this—how could they plan far ahead!" },
  { zh: "若捨而不追，必成後患。", literal: "If you abandon pursuit, you will surely breed future trouble.", idiomatic: "If you abandon pursuit, you will surely breed future trouble.\"" },
  { zh: "」歡不從，使劉豐生將數千騎追泰，遂東歸。", literal: "\" Huan did not follow the advice. He sent Liu Fengsheng with several thousand horse in pursuit of Tai, then turned east and returned.", idiomatic: "Huan did not follow the advice. He sent Liu Fengsheng with several thousand horse in pursuit of Tai, then turned east and returned." },
  { zh: "泰召王思政於玉壁，將使鎮虎牢，未至而泰敗，乃使守恆農。", literal: "Tai summoned Wang Sizheng from Yubi, intending to station him at Hulao; before Sizheng arrived Tai was defeated, so he was sent to hold Hengnong instead.", idiomatic: "Tai summoned Wang Sizheng from Yubi, intending to station him at Hulao; before Sizheng arrived Tai was defeated, so he was sent to hold Hengnong instead." },
  { zh: "思政入城，令開門解衣而臥，慰勉將士，示不足畏。", literal: "Sizheng entered the city, ordered the gates opened, stripped to his shirt, and lay down, encouraging the troops and showing he had nothing to fear.", idiomatic: "Sizheng entered the city, ordered the gates opened, stripped to his shirt, and lay down—encouraging the troops and showing he had nothing to fear." },
  { zh: "後數日，劉豐生至城下，憚之，不敢進，引軍還。", literal: "Several days later Liu Fengsheng reached the foot of the walls; he feared Sizheng, dared not advance, and withdrew his army.", idiomatic: "Several days later Liu Fengsheng reached the foot of the walls; he feared Sizheng, dared not advance, and withdrew his army." },
  { zh: "思政乃修城郭，起樓櫓，營農田，積芻粟，由是恆農始有守禦之備。", literal: "Sizheng then repaired the walls, raised towers and parapets, opened fields for garrison farming, and stored fodder and grain—whereby Hengnong first gained means of defense.", idiomatic: "Sizheng then repaired the walls, raised towers and parapets, opened fields for garrison farming, and stored fodder and grain—whereby Hengnong first gained real means of defense." },
  { zh: "丞相泰求自貶，魏主不許。", literal: "Chancellor Tai asked to be demoted; the Wei sovereign would not permit it.", idiomatic: "Chancellor Tai asked to be demoted; the Wei sovereign would not permit it." },
  { zh: "是役也，魏諸將皆無功，唯耿令貴與太子武衛率王胡仁、都督王文達力戰功多。", literal: "In this campaign the Wei generals all won no merit; only Geng Linggui, Crown Prince Martial Guard Commandant Wang Huren, and Supervisor Wang Wenda fought hard and achieved much.", idiomatic: "In this campaign the Wei generals all won no merit; only Geng Linggui, Crown Prince Martial Guard Commandant Wang Huren, and Supervisor Wang Wenda fought hard and achieved much." },
  { zh: "泰欲以雍、岐、北雍三州授之，以州有優劣，使探籌取之。", literal: "Tai wished to grant them Yong, Qi, and Northern Yong provinces; because the provinces differed in quality, he had them draw lots to choose.", idiomatic: "Tai wished to grant them Yong, Qi, and Northern Yong provinces; because the provinces differed in quality, he had them draw lots to choose." },
  { zh: "仍賜胡仁名勇，令貴名豪，文達名信，用彰其功。", literal: "He also bestowed on Huren the name Yong, on Linggui the name Hao, and on Wenda the name Xin, to make their merit manifest.", idiomatic: "He also bestowed on Huren the name Yong, on Linggui the name Hao, and on Wenda the name Xin, to make their merit manifest." },
  { zh: "於是廣募關、隴豪右以增軍旅。", literal: "Thereupon he widely recruited powerful families of Guan and Long to enlarge the army.", idiomatic: "Thereupon he widely recruited powerful families of Guan and Long to enlarge the army." },
  { zh: "高仲密之將叛也，陰遣人扇動冀州豪傑，使為內應，東魏遣高隆之馳驛慰撫，由是得安。", literal: "When Gao Zhongmi was about to rebel, he secretly sent men to stir the powerful families of Jizhou to act as inner supporters; Eastern Wei sent Gao Longzhi post-haste by relay to comfort and pacify them, and thus the region was kept quiet.", idiomatic: "When Gao Zhongmi was about to rebel, he secretly sent men to stir the powerful families of Jizhou to act as inner supporters; Eastern Wei sent Gao Longzhi post-haste by relay to comfort and pacify them, and thus the region was kept quiet." },
  { zh: "高澄密書與隆之曰：「仲密枝黨與之俱西者，宜悉收其家屬，以懲將來。", literal: "Gao Cheng sent a secret letter to Longzhi saying, \"Of Zhongmi's branch and party who went west with him, you should seize all their families to warn those who come after.", idiomatic: "Gao Cheng sent a secret letter to Longzhi saying, \"Of Zhongmi's branch and party who went west with him, you should seize all their families to warn those who come after.\"" },
  { zh: "」隆之以為恩旨既行，理無追改，若復收治，示民不信，脫致驚擾，所虧不細，乃啟丞相歡而罷之。", literal: "\" Longzhi held that since the grace-edict had already been issued, it was unreasonable to reverse it; if they seized and punished them again it would show the people the court did not keep faith, and should alarm and disturbance arise the loss would not be slight—he memorialized Chancellor Huan and the matter was dropped.", idiomatic: "Longzhi held that since the grace-edict had already been issued, it was unreasonable to reverse it; if they seized and punished them again it would show the people the court did not keep faith, and should alarm and disturbance arise the loss would not be slight—he memorialized Chancellor Huan and the matter was dropped." },
  { zh: "以太子詹事謝舉為尚書僕射。", literal: "Crown Prince Household Aide Xie Ju was made Vice Director of the Masters of Writing.", idiomatic: "Crown Prince Household Aide Xie Ju was made Vice Director of the Masters of Writing." },
  { zh: "夏，四月，林邑王攻李賁，賁將范修破林邑於九德。", literal: "In summer, the fourth month, the king of Linyi attacked Li Ben; Ben's general Fan Xiu defeated Linyi at Jiude.", idiomatic: "In summer, the fourth month, the king of Linyi attacked Li Ben; Ben's general Fan Xiu defeated Linyi at Jiude." },
  { zh: "清水氐酋李鼠仁，乘魏之敗，據險作亂；", literal: "Li Shuren, Di chieftain of Qingshui, took advantage of Wei's defeat to seize the passes and rise in rebellion;", idiomatic: "Li Shuren, Di chieftain of Qingshui, took advantage of Wei's defeat to seize the passes and rise in rebellion;" },
  { zh: "隴右大都督獨孤信屢遣軍擊之，不克。", literal: "Grand Commander of the Right Dugu Xin repeatedly sent troops to strike him but could not overcome him.", idiomatic: "Grand Commander of the Right Dugu Xin repeatedly sent troops to strike him but could not overcome him." },
  { zh: "丞相泰遣典簽天水趙昶往諭之，諸酋長聚議，或從或否；", literal: "Chancellor Tai sent Registry Clerk Zhao Chang of Tianshui to instruct them; the chieftains gathered to deliberate, some assenting and some refusing;", idiomatic: "Chancellor Tai sent Registry Clerk Zhao Chang of Tianshui to instruct them; the chieftains gathered to deliberate, some assenting and some refusing;" },
  { zh: "其不從者欲加刃於昶，昶神色自若，辭氣逾厲，鼠仁感悟，遂相帥降。", literal: "those who refused wished to set blades to Chang, but Chang's expression stayed calm and his words grew ever sterner; Shuren was moved to understanding, and they thereupon led one another in submission.", idiomatic: "those who refused wished to set blades to Chang, but Chang's expression stayed calm and his words grew ever sterner; Shuren was moved to understanding, and they thereupon led one another in submission." },
  { zh: "氐酋梁道顯叛，泰復遣昶諭降之，徙其豪帥四十餘人並部落於華州，泰即以昶為都督，使領之。", literal: "The Di chieftain Liang Daoxian rebelled; Tai again sent Chang to instruct him to submit, moved more than forty of their powerful chiefs together with their tribes to Huazhou, and made Chang colonel to command them.", idiomatic: "The Di chieftain Liang Daoxian rebelled; Tai again sent Chang to instruct him to submit, moved more than forty of their powerful chiefs together with their tribes to Huazhou, and made Chang colonel to command them." },
  { zh: "泰使諜潛入虎牢，令守將魏光固守。", literal: "Tai sent a spy secretly into Hulao and ordered the defending general Wei Guang to hold firm.", idiomatic: "Tai sent a spy secretly into Hulao and ordered the defending general Wei Guang to hold firm." },
  { zh: "侯景獲之，改其書云：「宜速去。", literal: "Hou Jing captured him and altered the letter to read, \"You should leave at once.", idiomatic: "Hou Jing captured him and altered the letter to read, \"You should leave at once.\"" },
  { zh: "」縱諜入城，光宵遁。", literal: "\" He released the spy into the city; Guang fled by night.", idiomatic: "He released the spy into the city; Guang fled by night." },
  { zh: "景獲高仲密妻子送鄴，北豫、洛二州復入於東魏。", literal: "Jing seized Gao Zhongmi's wife and children and sent them to Ye; Northern Yu and Luo provinces again fell to Eastern Wei.", idiomatic: "Jing seized Gao Zhongmi's wife and children and sent them to Ye; Northern Yu and Luo provinces again fell to Eastern Wei." },
  { zh: "五月，壬辰，東魏以克復虎牢，降死罪已下囚，唯不赦高仲密家。", literal: "In the fifth month, on renchen, Eastern Wei, for recovering Hulao, reduced the punishment of prisoners down to capital crimes, pardoning all below that rank, but did not pardon Zhongmi's household alone.", idiomatic: "In the fifth month, on renchen, Eastern Wei, for recovering Hulao, reduced the punishment of prisoners down to capital crimes, pardoning all below that rank, but did not pardon Zhongmi's household alone." },
  { zh: "丞相歡以高乾有義勳，高昂死王事，季式先自告，皆為之請，免其從坐。", literal: "Chancellor Huan, because Gao Gan had merit of righteousness, Gao Ang died in the king's service, and Jishi had reported himself first, all pleaded on their behalf and exempted them from joint punishment.", idiomatic: "Chancellor Huan, because Gao Gan had merit of righteousness, Gao Ang died in the king's service, and Jishi had reported himself first, all pleaded on their behalf and exempted them from joint punishment." },
  { zh: "仲密妻李氏當死，高澄盛服見之，曰：「今日何如？", literal: "Zhongmi's wife Lady Li was due for execution; Gao Cheng came to see her in full dress and said, \"How is it today?", idiomatic: "Zhongmi's wife Lady Li was due for execution; Gao Cheng came to see her in full dress and said, \"How is it today?\"" },
  { zh: "」李氏默然，遂納之。", literal: "\" Lady Li was silent; he thereupon took her in.", idiomatic: "Lady Li was silent; he thereupon took her in." },
  { zh: "乙未，以侯景為司空。", literal: "On yiwei, Hou Jing was made Minister of Works.", idiomatic: "On yiwei, Hou Jing was made Minister of Works." },
  { zh: "秋，七月，魏大赦。", literal: "In autumn, the seventh month, Wei proclaimed a general amnesty.", idiomatic: "In autumn, the seventh month, Wei proclaimed a general amnesty." },
  { zh: "以王盟為太傅，廣平王贊為司空。", literal: "Wang Meng was made Grand Tutor and the Prince of Guangping, Zan, Minister of Works.", idiomatic: "Wang Meng was made Grand Tutor and the Prince of Guangping, Zan, Minister of Works." },
  { zh: "八月，乙丑，東魏以汾州刺史斛律金為大司馬。", literal: "In the eighth month, on yichou, Eastern Wei made Fenzhou inspector Helü Jin Grand Marshal.", idiomatic: "In the eighth month, on yichou, Eastern Wei made Fenzhou inspector Helü Jin Grand Marshal." },
  { zh: "東魏遣兼散騎常侍李渾等來聘。", literal: "Eastern Wei sent Acting Palace Attendant Li Hun and others on a friendly embassy.", idiomatic: "Eastern Wei sent Acting Palace Attendant Li Hun and others on a friendly embassy." },
  { zh: "冬，十一月，甲午，東魏主狩於西山；", literal: "In winter, the eleventh month, on jiawu, the Eastern Wei ruler hunted on Western Mountain;", idiomatic: "In winter, the eleventh month, on jiawu, the Eastern Wei ruler hunted on Western Mountain;" },
  { zh: "乙巳，還宮。", literal: "on yisi he returned to the palace.", idiomatic: "on yisi he returned to the palace." },
  { zh: "高澄啟解侍中，東魏主以其弟并州刺史太原公洋代之。", literal: "Gao Cheng memorialized to resign as Palace Attendant; the Eastern Wei ruler had his younger brother, Bingzhou inspector the Duke of Taiyuan, Yang, replace him.", idiomatic: "Gao Cheng memorialized to resign as Palace Attendant; the Eastern Wei ruler had his younger brother, Bingzhou inspector the Duke of Taiyuan, Yang, replace him." },
  { zh: "丞相歡築長城於肆州北山，西自馬陵，東至土□登，四十日罷。", literal: "Chancellor Huan built a long wall on the northern mountains of Sizhou, west from Maling east to Tudeng, finishing in forty days.", idiomatic: "Chancellor Huan built a long wall on the northern mountains of Sizhou, west from Maling east to Tudeng, finishing in forty days." },
  { zh: "魏諸牧守共謁丞相泰，泰命河北太守裴俠別立，謂諸牧守曰：「裴俠清慎奉公，為天下最。", literal: "The Wei prefects and governors all came to call on Chancellor Tai; Tai ordered Hebei prefect Pei Xia to stand apart and said to the prefects and governors, \"Pei Xia is pure, cautious, and serves the public—he is the finest under Heaven.", idiomatic: "The Wei prefects and governors all came to call on Chancellor Tai; Tai ordered Hebei prefect Pei Xia to stand apart and said to the prefects and governors, \"Pei Xia is pure, cautious, and serves the public—he is the finest under Heaven." },
  { zh: "有如俠者，可與俱立！", literal: "If any are like Xia, you may stand with him!", idiomatic: "If any are like Xia, you may stand with him!\"" },
  { zh: "」眾默然，無敢應者。", literal: "\" All were silent; none dared answer.", idiomatic: "All were silent; none dared answer." },
  { zh: "泰乃厚賜俠，朝野歎服，號為「獨立君」。", literal: "Tai then richly rewarded Xia; court and countryside admired him and called him \"the Stand-Alone Lord.\"", idiomatic: "Tai then richly rewarded Xia; court and countryside admired him and called him \"the Stand-Alone Lord.\"" },
  { zh: "高祖武皇帝十四大同十年（", literal: "Great Ancestor Emperor Wu, fourteenth year of Datong (", idiomatic: "Emperor Wu of Liang, fourteenth year of Datong (" },
  { zh: "甲子，公元五四四年）", literal: "jiazi, 544 CE)", idiomatic: "jiazi, AD 544)" },
  { zh: "春，正月，李賁自稱越帝，置百官，改元天德。", literal: "In spring, the first month, Li Ben styled himself Emperor of Yue, set up the hundred offices, and changed the era name to Tiande.", idiomatic: "In spring, the first month, Li Ben styled himself Emperor of Yue, set up the hundred offices, and changed the era name to Tiande." },
  { zh: "三月，癸巳，東魏丞相歡巡行冀、定二州，校河北戶口損益，因朝於鄴。", literal: "In the third month, on guisi, Eastern Wei Chancellor Huan toured Jizhou and Dingzhou, checked the gain and loss of household registers north of the Yellow River, and on that account attended court at Ye.", idiomatic: "In the third month, on guisi, Eastern Wei Chancellor Huan toured Jizhou and Dingzhou, checked the gain and loss of household registers north of the Yellow River, and on that account attended court at Ye." },
  { zh: "甲午，上幸蘭陵，謁建寧陵，使太子入守宮城；", literal: "On jiawu the emperor visited Lanling, paid respects at Jianning Mausoleum, and had the crown prince enter to guard the palace;", idiomatic: "On jiawu the emperor visited Lanling, paid respects at Jianning Mausoleum, and had the crown prince enter to guard the palace;" },
  { zh: "辛丑，謁脩陵。", literal: "on xinchou he paid respects at Xiuling.", idiomatic: "on xinchou he paid respects at Xiuling." },
  { zh: "丙午，東魏以開府儀同三司孫騰為太保。", literal: "On bingwu, Eastern Wei made Palace Gate General of the First Rank Sun Teng Grand Guardian.", idiomatic: "On bingwu, Eastern Wei made Palace Gate General of the First Rank Sun Teng Grand Guardian." },
  { zh: "己酉，上幸京口城北固樓，更名北顧；", literal: "On jiyou the emperor visited the Beigu Tower north of Jingkou and renamed it North Gaze;", idiomatic: "On jiyou the emperor visited the Beigu Tower north of Jingkou and renamed it North Gaze;" },
  { zh: "庚戌，幸回賓亭，宴鄉里故老及所經近縣迎候者，少長數千人，各賚錢二千。", literal: "on gengxu he visited Huibin Pavilion, feasted the elders of his native place and those from nearby counties who had come to welcome him—young and old numbering several thousand—and gave each two thousand cash.", idiomatic: "on gengxu he visited Huibin Pavilion, feasted the elders of his native place and those from nearby counties who had come to welcome him—young and old numbering several thousand—and gave each two thousand cash." },
  { zh: "壬子，東魏以高澄為大將軍、領中書監，元弼為錄尚書事，左僕射司馬子如為尚書令，侍中高洋為左僕射。", literal: "On renzi, Eastern Wei made Gao Cheng Grand General and Director of the Masters of Writing, Yuan Bi Recorder of the Affairs of the Masters of Writing, Left Vice Director Sima Ziru Director of the Masters of Writing, and Palace Attendant Gao Yang Left Vice Director.", idiomatic: "On renzi, Eastern Wei made Gao Cheng Grand General and Director of the Masters of Writing, Yuan Bi Recorder of the Affairs of the Masters of Writing, Left Vice Director Sima Ziru Director of the Masters of Writing, and Palace Attendant Gao Yang Left Vice Director." },
  { zh: "丞相歡多在晉陽，孫騰、司馬子如、高岳、高隆之，皆歡之親舊，委以朝政，鄴中謂之四貴，其權勢熏灼中外，率多專恣驕貪。", literal: "Chancellor Huan was often at Jinyang; Sun Teng, Sima Ziru, Gao Yue, and Gao Longzhi were all Huan's intimates, entrusted with court government—Ye called them the Four Dignitaries; their power scorched within and without, and for the most part they were willful, arrogant, and greedy.", idiomatic: "Chancellor Huan was often at Jinyang; Sun Teng, Sima Ziru, Gao Yue, and Gao Longzhi were all Huan's intimates, entrusted with court government—Ye called them the Four Dignitaries; their power scorched within and without, and for the most part they were willful, arrogant, and greedy." },
  { zh: "歡欲損奪其權，故以澄為大將軍、領中書監，移門下機事總歸中書，文武賞罰皆稟於澄。", literal: "Huan wished to curtail their power, and therefore made Cheng Grand General and Director of the Masters of Writing, shifting the Secretariat's business in total to the Masters of Writing; civil and military rewards and punishments all were reported to Cheng.", idiomatic: "Huan wished to curtail their power, and therefore made Cheng Grand General and Director of the Masters of Writing, shifting the Secretariat's business in total to the Masters of Writing; civil and military rewards and punishments all were reported to Cheng." },
  { zh: "孫騰見澄，不肯盡敬，澄叱左右牽下於床，築以刀環，立之門外。", literal: "When Sun Teng saw Cheng he would not show full respect; Cheng shouted for attendants to drag him down from the couch, beat him with sword rings, and set him standing outside the gate.", idiomatic: "When Sun Teng saw Cheng he would not show full respect; Cheng shouted for attendants to drag him down from the couch, beat him with sword rings, and set him standing outside the gate." },
  { zh: "太原公洋於澄前拜高隆之，呼為叔父，澄怒罵之。", literal: "The Duke of Taiyuan, Yang, bowed to Gao Longzhi before Cheng and called him uncle; Cheng cursed him in anger.", idiomatic: "The Duke of Taiyuan, Yang, bowed to Gao Longzhi before Cheng and called him uncle; Cheng cursed him in anger." },
  { zh: "歡謂群公曰：「兒子浸長，公宜避之。", literal: "Huan told the assembled lords, \"Sons grow daily; you lords ought to give way.", idiomatic: "Huan told the assembled lords, \"Sons grow daily; you lords ought to give way.\"" },
  { zh: "」於是公卿以下，見澄無不聳懼。", literal: "\" Thereupon from the dukes and ministers downward, all who saw Cheng did so in dread.", idiomatic: "Thereupon from the dukes and ministers downward, all who saw Cheng did so in dread." },
  { zh: "庫狄干，澄姑之婿也，自定州來謁，立於門外，三日乃得見。", literal: "Kudi Gan, Cheng's aunt's son-in-law, came from Dingzhou to call; he stood outside the gate three days before he was received.", idiomatic: "Kudi Gan, Cheng's aunt's son-in-law, came from Dingzhou to call; he stood outside the gate three days before he was received." },
  { zh: "澄欲置腹心於東魏主左右，擢中兵參軍崔季舒為中書侍郎。", literal: "Cheng wished to place trusted men at the Eastern Wei ruler's side and promoted Central Army Staff Member Cui Jishu to Secretariat Attendant.", idiomatic: "Cheng wished to place trusted men at the Eastern Wei ruler's side and promoted Central Army Staff Member Cui Jishu to Secretariat Attendant." },
  { zh: "澄每進書於帝，有所諫請，或文辭繁雜，季舒輒修飾通之。", literal: "Whenever Cheng forwarded a memorial to the emperor with remonstrance or request, if the wording was tangled Jishu would revise and make it clear.", idiomatic: "Whenever Cheng forwarded a memorial to the emperor with remonstrance or request, if the wording was tangled Jishu would revise and make it clear." },
  { zh: "帝報澄父子之語，常與季舒論之，曰：「崔中書，我乳母也。", literal: "The emperor, in reporting Cheng and his father's words, often discussed them with Jishu and said, \"Director Cui is my wet nurse.", idiomatic: "The emperor, in reporting Cheng and his father's words, often discussed them with Jishu and said, \"Director Cui is my wet nurse.\"" },
  { zh: "」季舒，挺之從子也。", literal: "\" Jishu was a nephew of Cui Ting's.", idiomatic: "Jishu was a nephew of Cui Ting's." },
  { zh: "夏，四月，乙卯，上還自蘭陵。", literal: "In summer, the fourth month, on yimao, the emperor returned from Lanling.", idiomatic: "In summer, the fourth month, on yimao, the emperor returned from Lanling." },
  { zh: "五月，甲申朔，魏丞相泰朝於長安。", literal: "In the fifth month, on the new moon of jiashen, Wei Chancellor Tai attended court at Chang'an.", idiomatic: "In the fifth month, on the new moon of jiashen, Wei Chancellor Tai attended court at Chang'an." },
  { zh: "甲午，東魏遣散騎常侍魏季景來聘。", literal: "On jiawu, Eastern Wei sent Palace Attendant Wei Jijing on a friendly embassy.", idiomatic: "On jiawu, Eastern Wei sent Palace Attendant Wei Jijing on a friendly embassy." },
  { zh: "季景，收之族叔也。", literal: "Jijing was a clansman of Wei Shou.", idiomatic: "Jijing was a clansman of Wei Shou." },
  { zh: "尚書令何敬容妾弟盜官米，以書屬領軍河東王譽；", literal: "Director of the Masters of Writing He Jingrong's younger brother by a concubine stole official grain and used a letter to ask Military Supervisor Prince Yu of Hedong for favor;", idiomatic: "Director of the Masters of Writing He Jingrong's younger brother by a concubine stole official grain and used a letter to ask Military Supervisor Prince Yu of Hedong for favor;" },
  { zh: "丁酉，敬容坐免官。", literal: "on dingyou Jingrong was removed from office for the crime.", idiomatic: "on dingyou Jingrong was removed from office for the crime." },
  { zh: "東魏廣陽王湛卒。", literal: "Eastern Wei Prince Zhan of Guangyang died.", idiomatic: "Eastern Wei Prince Zhan of Guangyang died." },
  { zh: "魏琅邪貞獻公賀拔勝諸子在東者，丞相歡盡殺之，勝憤恨發疾而卒。", literal: "The sons of Wei Duke of Langye, the Loyal and Offering Helüba Sheng, who were in the east, Chancellor Huan killed them all; Sheng died of rage and illness.", idiomatic: "The sons of Wei Duke of Langye, the Loyal and Offering Helüba Sheng, who were in the east, Chancellor Huan killed them all; Sheng died of rage and illness." },
  { zh: "丞相泰常謂人曰：「諸將對敵神色皆動，唯賀拔公臨陳如平時，真大勇也！", literal: "Chancellor Tai often told others, \"When the generals face the enemy their expressions all change; only Duke Helüba at battle is as at ordinary times—true great courage!", idiomatic: "Chancellor Tai often told others, \"When the generals face the enemy their expressions all change; only Duke Helüba at battle is as at ordinary times—true great courage!\"" },
  { zh: "秋，七月，魏更權衡度量，命尚書蘇綽損益三十六條之制，總為五卷，頒行之。", literal: "In autumn, the seventh month, Wei revised weights and measures, ordered Master of Writing Su Chuo to revise the thirty-six-article code for gain and loss, compiled it in five scrolls in all, and promulgated it.", idiomatic: "In autumn, the seventh month, Wei revised weights and measures, ordered Master of Writing Su Chuo to revise the thirty-six-article code for gain and loss, compiled it in five scrolls in all, and promulgated it." },
  { zh: "搜簡賢才為牧守令長，皆依新制而遣焉。", literal: "He searched out the worthy to be prefects, governors, and magistrates, and dispatched them all according to the new code.", idiomatic: "He searched out the worthy to be prefects, governors, and magistrates, and dispatched them all according to the new code." },
  { zh: "數年之間，百姓便之。", literal: "Within several years the common people found it convenient.", idiomatic: "Within several years the common people found it convenient." },
  { zh: "魏自正光以後，政刑弛縱，在位多貪污。", literal: "From Zhenguang onward Wei government and punishments had grown lax; those in office were mostly corrupt.", idiomatic: "From Zhenguang onward Wei government and punishments had grown lax; those in office were mostly corrupt." },
  { zh: "丞相歡啟以司州中從事宋游道為御史中尉，澄固請以吏部郎崔暹為之，以游道為尚書左丞。", literal: "Chancellor Huan memorialized to make Song Youdao of Sizhou Central Army Attendant Censor-in-Chief; Cheng firmly asked that Ministry of Personnel Attendant Cui Xuan be made to the post, with Youdao as Left Vice Director of the Masters of Writing.", idiomatic: "Chancellor Huan memorialized to make Song Youdao of Sizhou Central Army Attendant Censor-in-Chief; Cheng firmly asked that Ministry of Personnel Attendant Cui Xuan be made to the post, with Youdao as Left Vice Director of the Masters of Writing." },
  { zh: "澄謂暹、游道曰：「卿一人處南台，一人處北省，當使天下肅然。", literal: "Cheng told Xuan and Youdao, \"You, one at the Southern Terrace and one at the Northern Bureau, should make all under Heaven stand in awe.", idiomatic: "Cheng told Xuan and Youdao, \"You, one at the Southern Terrace and one at the Northern Bureau, should make all under Heaven stand in awe.\"" },
  { zh: "」暹選畢義雲等為御史，時稱得人。", literal: "\" Xuan chose Bi Yiyun and others as censors; the age called it obtaining the right men.", idiomatic: "Xuan chose Bi Yiyun and others as censors; the age called it obtaining the right men." },
  { zh: "義雲，眾敬之曾孫也。", literal: "Yiyun was a great-grandson of Bi Zhongjing.", idiomatic: "Yiyun was a great-grandson of Bi Zhongjing." },
  { zh: "澄欲假暹威勢，諸公在坐，令暹後至，通名，高視徐步，兩人挈裾而入；", literal: "Cheng wished to borrow Xuan's awesomeness; when the lords were seated he had Xuan arrive last, announce his name, walk in with high gaze and slow step, two men lifting his robe;", idiomatic: "Cheng wished to borrow Xuan's awesomeness; when the lords were seated he had Xuan arrive last, announce his name, walk in with high gaze and slow step, two men lifting his robe;" },
  { zh: "澄分庭對揖，暹不讓而坐，觴再行，即辭去。", literal: "Cheng met him with equal bows across the courtyard; Xuan did not yield but sat, and after two rounds of wine at once took leave.", idiomatic: "Cheng met him with equal bows across the courtyard; Xuan did not yield but sat, and after two rounds of wine at once took leave." },
  { zh: "澄留之食，暹曰：「適受敕在台檢校。", literal: "Cheng kept him to eat; Xuan said, \"I have just received orders to inspect at the Terrace.", idiomatic: "Cheng kept him to eat; Xuan said, \"I have just received orders to inspect at the Terrace.\"" },
  { zh: "」遂不待食而去，澄降階送之。", literal: "\" He thereupon left without waiting for the meal; Cheng descended the steps to see him off.", idiomatic: "He thereupon left without waiting for the meal; Cheng descended the steps to see him off." },
  { zh: "它日，澄與諸公出，之東山，遇暹於道，前驅為赤棒所擊，澄回馬避之。", literal: "Another day Cheng went out with the lords to Eastern Mountain and met Xuan on the road; the outriders were struck by red staffs and Cheng turned his horse aside.", idiomatic: "Another day Cheng went out with the lords to Eastern Mountain and met Xuan on the road; the outriders were struck by red staffs and Cheng turned his horse aside." },
  { zh: "尚書令司馬子如以丞相歡故人，當重任，意氣自高，與太師咸陽王坦貪黷無厭；", literal: "Director of the Masters of Writing Sima Ziru, as Chancellor Huan's old friend, held heavy responsibility and was proud in spirit; he and Grand Master Prince Tan of Xianyang were insatiably greedy;", idiomatic: "Director of the Masters of Writing Sima Ziru, as Chancellor Huan's old friend, held heavy responsibility and was proud in spirit; he and Grand Master Prince Tan of Xianyang were insatiably greedy;" },
  { zh: "暹前後彈子如、坦及并州刺史可朱渾道元等罪狀，無不極筆。", literal: "Xuan impeached Ziru, Tan, and Bingzhou inspector Kezhunhun Daoyuan and others for crimes, in every case to the full limit of the brush.", idiomatic: "Xuan impeached Ziru, Tan, and Bingzhou inspector Kezhunhun Daoyuan and others for crimes, in every case to the full limit of the brush." },
  { zh: "宋游道亦劾子如、坦及太保孫騰、司徒高隆之、司空侯景、尚書元羨等。", literal: "Song Youdao also impeached Ziru, Tan, and Grand Guardian Sun Teng, Minister of Works Gao Longzhi, Minister of Works Hou Jing, and Master of Writing Yuan Xian and others.", idiomatic: "Song Youdao also impeached Ziru, Tan, and Grand Guardian Sun Teng, Minister of Works Gao Longzhi, Minister of Works Hou Jing, and Master of Writing Yuan Xian and others." },
  { zh: "澄收子如繫獄，一宿，發盡白，辭曰：「司馬子如從夏州策杖投相王，王給露車一乘，豢牸牛犢，犢在道死，唯豢角存，此外皆取之於人。", literal: "Cheng seized Ziru and imprisoned him; in one night his hair turned entirely white. His statement read, \"Sima Ziru came from Xiazhou leaning on a staff to join the Prince-Regent; the Prince gave one covered cart, a cow and calf for rearing—the calf died on the road and only the horns of the rearing cow remain; beyond that everything was taken from others.", idiomatic: "Cheng seized Ziru and imprisoned him; in one night his hair turned entirely white. His statement read, \"Sima Ziru came from Xiazhou leaning on a staff to join the Prince-Regent; the Prince gave one covered cart, a cow and calf for rearing—the calf died on the road and only the horns of the rearing cow remain; beyond that everything was taken from others.\"" },
  { zh: "」丞相歡以書敕澄曰：「司馬令，吾之故舊，汝宜寬之。", literal: "\" Chancellor Huan sent a letter commanding Cheng, \"Director Sima is my old friend; you should treat him leniently.", idiomatic: "Chancellor Huan sent a letter commanding Cheng, \"Director Sima is my old friend; you should treat him leniently.\"" },
  { zh: "」澄駐馬行街，出子如，脫其鎖；", literal: "\" Cheng halted his horse in the street, released Ziru, and removed his fetters;", idiomatic: "Cheng halted his horse in the street, released Ziru, and removed his fetters;" },
  { zh: "子如懼曰：「非作事邪？", literal: "Ziru said in fear, \"This is not a capital case?", idiomatic: "Ziru said in fear, \"This is not a capital case?\"" },
  { zh: "」八月，癸酉，削子如官爵。", literal: "\" In the eighth month, on guiyou, Ziru's office and rank were stripped.", idiomatic: "In the eighth month, on guiyou, Ziru's office and rank were stripped." },
  { zh: "九月，甲申，以濟陰王暉業為太尉；", literal: "In the ninth month, on jiashen, Prince Ye of Jiyin was made Grand Commandant;", idiomatic: "In the ninth month, on jiashen, Prince Ye of Jiyin was made Grand Commandant;" },
  { zh: "太師咸陽王坦以王還第，元羨等皆免官，其餘死黜者甚眾。", literal: "Grand Master Prince Tan of Xianyang was returned to his estate as a prince; Yuan Xian and others were all removed from office, and of the rest many were executed or dismissed.", idiomatic: "Grand Master Prince Tan of Xianyang was returned to his estate as a prince; Yuan Xian and others were all removed from office, and of the rest many were executed or dismissed." },
  { zh: "久之，歡見子如，哀其憔悴，以膝承其首，親為擇虱，賜酒百瓶，羊五百口，米五百石。", literal: "After a long while Huan saw Ziru, pitied his haggard look, supported his head on his knee, personally picked lice for him, and gave a hundred jars of wine, five hundred sheep, and five hundred piculs of grain.", idiomatic: "After a long while Huan saw Ziru, pitied his haggard look, supported his head on his knee, personally picked lice for him, and gave a hundred jars of wine, five hundred sheep, and five hundred piculs of grain." },
  { zh: "高澄對諸貴極言褒美崔暹，且戒屬之。", literal: "Gao Cheng spoke to the dignitaries at length in praise of Cui Xuan and also warned them to heed him.", idiomatic: "Gao Cheng spoke to the dignitaries at length in praise of Cui Xuan and also warned them to heed him." },
  { zh: "丞相歡書與鄴下諸貴曰：「崔暹居憲台，咸陽王、司馬令皆吾布衣之舊，尊貴親暱，無過二人，同時獲罪，吾不能救，諸君其慎之！", literal: "Chancellor Huan wrote to the dignitaries at Ye, \"Cui Xuan holds the Censorate; Prince Tan of Xianyang and Director Sima are both my old companions in plain cloth—none more honored or intimate than those two—yet both fell into crime at once and I could not save them; you lords, take care!", idiomatic: "Chancellor Huan wrote to the dignitaries at Ye, \"Cui Xuan holds the Censorate; Prince Tan of Xianyang and Director Sima are both my old companions in plain cloth—none more honored or intimate than those two—yet both fell into crime at once and I could not save them; you lords, take care!\"" },
  { zh: "宋游道奏駁尚書違失數百條，省中豪吏王儒之徒並鞭斥之，令、僕已下皆側目。", literal: "Song Youdao memorialized to refute several hundred errors of the Masters of Writing; the powerful clerks Wang Ru and others in the bureau were all flogged and driven out, and from directors and vice directors downward all looked askance.", idiomatic: "Song Youdao memorialized to refute several hundred errors of the Masters of Writing; the powerful clerks Wang Ru and others in the bureau were all flogged and driven out, and from directors and vice directors downward all looked askance." },
  { zh: "高隆之誣游道有不臣之言，罪當死。", literal: "Gao Longzhi slandered Youdao with words of disloyalty; the crime merited death.", idiomatic: "Gao Longzhi slandered Youdao with words of disloyalty; the crime merited death." },
  { zh: "給事黃門侍郎楊愔曰：「畜狗求吠；", literal: "Palace Attendant Yang Yin said, \"One keeps a dog to make it bark;", idiomatic: "Palace Attendant Yang Yin said, \"One keeps a dog to make it bark;" },
  { zh: "今以數吠殺之，恐將來無復吠狗。", literal: "now you kill it for barking a few times—I fear hereafter there will be no dog left to bark.", idiomatic: "now you kill it for barking a few times—I fear hereafter there will be no dog left to bark.\"" },
  { zh: "」游道竟坐除名。", literal: "\" Youdao was punished by removal from office in the end.", idiomatic: "Youdao was punished by removal from office in the end." },
  { zh: "澄謂游道曰：「卿早從我向并州，不爾，彼經略殺卿。", literal: "Cheng told Youdao, \"If you had followed me early to Bingzhou it would not have been so; otherwise Longzhi would have killed you.", idiomatic: "Cheng told Youdao, \"If you had followed me early to Bingzhou it would not have been so; otherwise Longzhi would have killed you.\"" },
  { zh: "」游道從澄至晉陽，以為大行台吏部。", literal: "\" Youdao followed Cheng to Jinyang and was made Personnel Director of the Grand Eastern Office.", idiomatic: "Youdao followed Cheng to Jinyang and was made Personnel Director of the Grand Eastern Office." },
  { zh: "己丑，大赦。", literal: "On jichou, a general amnesty.", idiomatic: "On jichou, a general amnesty." },
  { zh: "東魏以喪亂之後，戶口失實，徭賦不均。", literal: "After the disorders Eastern Wei's household registers no longer matched reality and corvée and tax were uneven.", idiomatic: "After the disorders Eastern Wei's household registers no longer matched reality and corvée and tax were uneven." },
  { zh: "冬，十月，丁巳，以太保孫騰、大司徒高隆之為括戶大使，分行諸州，得無籍之戶六十餘萬，僑居者皆勒還本屬。", literal: "In winter, the tenth month, on dingsi, Grand Guardian Sun Teng and Grand Minister of Works Gao Longzhi were made commissioners for registering households, touring the provinces separately; they obtained more than six hundred thousand households without registers, and all who had moved away were compelled to return to their original jurisdictions.", idiomatic: "In winter, the tenth month, on dingsi, Grand Guardian Sun Teng and Grand Minister of Works Gao Longzhi were made commissioners for registering households, touring the provinces separately; they obtained more than six hundred thousand households without registers, and all who had moved away were compelled to return to their original jurisdictions." },
  { zh: "十一月，甲申，以高隆之錄尚書事，以前大司馬婁昭為司徒。", literal: "In the eleventh month, on jiashen, Gao Longzhi was made Recorder of the Affairs of the Masters of Writing, and former Grand Marshal Lou Zhao Minister of Works.", idiomatic: "In the eleventh month, on jiashen, Gao Longzhi was made Recorder of the Affairs of the Masters of Writing, and former Grand Marshal Lou Zhao Minister of Works." },
  { zh: "庚子，東魏主祀圜丘。", literal: "On gengzi the Eastern Wei ruler sacrificed at the Round Mound.", idiomatic: "On gengzi the Eastern Wei ruler sacrificed at the Round Mound." },
  { zh: "東魏丞相歡襲擊山胡，破之，俘萬餘戶，分配諸州。", literal: "Eastern Wei Chancellor Huan raided the Mountain Hu, defeated them, captured more than ten thousand households, and distributed them among the provinces.", idiomatic: "Eastern Wei Chancellor Huan raided the Mountain Hu, defeated them, captured more than ten thousand households, and distributed them among the provinces." },
  { zh: "是歲，東魏以散騎常侍魏收兼中書侍郎，修國史。", literal: "That year Eastern Wei made Acting Palace Attendant Wei Shou also Secretariat Attendant to compile the national history.", idiomatic: "That year Eastern Wei made Acting Palace Attendant Wei Shou also Secretariat Attendant to compile the national history." },
  { zh: "自梁、魏通好，魏書每云：「想彼境內寧靜，此率土安和。", literal: "Since Liang and Wei were on good terms, Wei letters always said, \"We trust your realm is tranquil within; our whole land is at peace.", idiomatic: "Since Liang and Wei were on good terms, Wei letters always said, \"We trust your realm is tranquil within; our whole land is at peace.\"" },
  { zh: "」上復書，去「彼」字而已。", literal: "\" The emperor in reply removed only the word \"your.", idiomatic: "The emperor in reply removed only the word \"your.\"" },
  { zh: "收始定書云：「想境內清晏，今萬里安和。", literal: "Shou first fixed the letter to read, \"We trust the realm is clear and calm; now ten thousand li are at peace.", idiomatic: "Shou first fixed the letter to read, \"We trust the realm is clear and calm; now ten thousand li are at peace.\"" },
  { zh: "」上亦效之。", literal: "\" The emperor imitated that as well.", idiomatic: "The emperor imitated that as well." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "Category: Comprehensive Mirror in Aid of Governance" },
];
